	/**
	 * ES 사전 색인 조회용 클래스
	 * 사전 컴파일 등에 사용한다.
	 */
	public static class DictionarySource extends DictionaryRepository implements Iterator<CharSequence[]> {
		private Client client;
		private RemoteNodeClient remoteClient;
		private String index;
		private Iterator<Map<String, Object>> iterator;
		private List<Map<String, Object>> remoteResults;
		private int remoteIndex;

		public DictionarySource(Client client, String index) {
			this.client = client;
			this.index = index;
		}

		public DictionarySource(RemoteNodeClient remoteClient, String index) {
			this.remoteClient = remoteClient;
			this.index = index;
		}

		@Override public Iterator<CharSequence[]> getSource(String type) {
			try {
				QueryBuilder query = QueryBuilders.matchQuery(ES_DICT_FIELD_TYPE, type.toUpperCase());
				logger.trace("QUERY:{}", query);

				if (remoteClient != null) {
					// RemoteNodeClient를 사용한 원격 검색
					remoteResults = new ArrayList<>();
					remoteIndex = 0;
					org.elasticsearch.action.search.SearchRequest searchRequest = new org.elasticsearch.action.search.SearchRequest();
					org.elasticsearch.search.builder.SearchSourceBuilder sourceBuilder = new org.elasticsearch.search.builder.SearchSourceBuilder();
					sourceBuilder.query(query).size(10000);
					searchRequest.indices(index).source(sourceBuilder);

					JSONObject response = remoteClient.search(searchRequest);
					if (response != null && response.has("hits")) {
						JSONObject hits = response.getJSONObject("hits");
						org.json.JSONArray hitsArray = hits.getJSONArray("hits");
						for (int i = 0; i < hitsArray.length(); i++) {
							JSONObject hit = hitsArray.getJSONObject(i);
							JSONObject source = hit.getJSONObject("_source");
							Map<String, Object> map = new HashMap<>();
							for (String key : source.keySet()) {
								map.put(key, source.get(key));
							}
							remoteResults.add(map);
						}
					}
				} else {
					// 로컬 Client를 사용한 검색
					iterator = SearchUtil.search(client, index, query, null, null, 0, -1, true, null);
				}
			} catch (Exception e) {
				logger.error("", e);
			}
			return this;
		}

		@Override public void restore(String type, boolean ignoreCase, Set<CharSequence> wordSet) {
			if (client == null) {
				logger.warn("restore() is not supported for RemoteNodeClient");
				return;
			}
			Map<String, Object> source = null;
			BulkRequestBuilder builder = null;
			try {
				builder = client.prepareBulk();
				int inx = 0;
				for (CharSequence data : wordSet) {
					String[] words = String.valueOf(data).split(TAB);
					source = new HashMap<>();
					source.put(ES_DICT_FIELD_TYPE, type.toUpperCase());
					if (words.length == 1) {
						source.put(ES_DICT_FIELD_KEYWORD, words[0]);
					} else if (words.length == 2) {
						if (words[0].length() > 0) {
							source.put(ES_DICT_FIELD_KEYWORD, words[0]);
						}
						source.put(ES_DICT_FIELD_VALUE, words[1]);
					} else {
						source.put(ES_DICT_FIELD_KEYWORD, words[0]);
						source.put(ES_DICT_FIELD_VALUE, words[1]);
						source.put(ES_DICT_FIELD_ID, words[2]);
					}
					builder.add(client.prepareIndex(String.valueOf(index)).setSource(source));
					if (inx > 0 && inx % 1000 == 0) {
						builder.execute().actionGet();
						builder = client.prepareBulk();
					}
					inx++;
				}
				if (inx > 0) {
					builder.execute().actionGet();
				}
			} catch (Exception e) {
				logger.error("", e);
			}
		}

		@Override public boolean hasNext() {
			if (remoteClient != null) {
				return remoteResults != null && remoteIndex < remoteResults.size();
			}
			return iterator != null && iterator.hasNext();
		}

		@Override public CharSequence[] next() {
			Map<String, Object> data;
			if (remoteClient != null) {
				data = remoteResults.get(remoteIndex++);
			} else {
				data = iterator.next();
			}
			CharSequence id = CharVector.valueOf(data.get(ES_DICT_FIELD_ID));
			CharSequence keyword = CharVector.valueOf(data.get(ES_DICT_FIELD_KEYWORD));
			CharSequence value = CharVector.valueOf(data.get(ES_DICT_FIELD_VALUE));
			return new CharSequence[] { id, keyword, value };
		}

		@Override public void close() { }
	}

	private void getSynonymListAction(RestRequest request, NodeClient client, JSONWriter writer){
		JSONObject jparam = new JSONObject();
		String keyword = "";
		boolean useForQuery = true;
		boolean useSynonym = true;
		boolean useStopword = false;
		boolean useFullString = true;

		logger.debug("get-synonym-list start");
		if (!GET.equals(request.method())) {
			jparam = parseRequestBody(request);
			keyword = jparam.optString("keyword", "");
		} else {
			try{
				keyword = URLDecoder.decode(request.param("keyword", ""), "UTF-8");
			} catch (UnsupportedEncodingException e){
				logger.error("UnsupportedEncodingException Catched !!! >>>> \n" + e.getMessage());
				logger.debug("error >>> {}", e);
			}
		}

		TokenStream stream = null;
		try {
			writer.key("query").value(keyword);
			writer.key("result").array();
			stream = ProductNameAnalyzerProvider.getAnalyzer(keyword, useForQuery, useSynonym, useStopword, useFullString, false);
			getSynonymList(keyword, stream, writer);
			writer.endArray();
			writer.key("success").value(true);
		} finally {
			try {
				stream.close();
			} catch (Exception ignore) {
				logger.debug("Exception >>> {}", ignore.getMessage());
			}
		}
	}

	/**
	 * 동의어 리스트.
	 */
	public static void getSynonymList(String text, TokenStream stream, JSONWriter writer) {
		CharTermAttribute termAttr = stream.addAttribute(CharTermAttribute.class);
		TypeAttribute typeAttr = stream.addAttribute(TypeAttribute.class);
		SynonymAttribute synAttr = stream.addAttribute(SynonymAttribute.class);
		Map<String, List<List<String>>> result = new HashMap<>();
		List<CharSequence> synonyms = synAttr.getSynonyms();

		for (String key : ANALYSIS_RESULT_LABELS.keySet()) {
			result.put(key, new ArrayList<>());
		}

		String term = null;
		String type = null;
		String setName = null;
		try {
			stream.reset();
			while (stream.incrementToken()) {
				term = String.valueOf(termAttr);
				type = typeAttr.type();
				logger.trace("TERM:{} / {}", term, type);
				if (ProductNameTokenizer.FULL_STRING.equals(type)) {
					// 전체 단어
					setName = ANALYZE_SET_FULL_STRING;
					setAnalyzedResult(result, term, ANALYZE_SET_FULL_STRING, ANALYZE_SET_FINAL);
				} else if (ProductNameTokenizer.MODEL_NAME.equals(type)) {
					// 모델명의 경우 색인시와 질의시 추출방법이 서로 다르다.
					setName = ANALYZE_SET_MODEL_NAME;
					setAnalyzedResult(result, term, ANALYZE_SET_MODEL_NAME, ANALYZE_SET_FINAL);
				} else {
					// 일반단어
					setName = ANALYZE_SET_NORMAL;
					setAnalyzedResult(result, term, ANALYZE_SET_NORMAL, ANALYZE_SET_FINAL);
				}

				if (!ANALYZE_SET_FULL_STRING.equals(setName)) {
					if ((synonyms = synAttr.getSynonyms()) != null && synonyms.size() > 0) {
						if (term.equals(text)) {
							for (CharSequence synonym : synonyms) {
								String s = String.valueOf(synonym);
								writer.value(s);
							}
						}

					}
				}
			}
		} catch (Exception e) {
			logger.error("", e);
		}
	}
}

package com.danawa.search.analysis.product

import com.danawa.search.analysis.dict.ProductNameDictionary
import com.danawa.util.ContextStore
import org.apache.lucene.analysis.Analyzer
import org.apache.lucene.analysis.TokenStream
import org.apache.lucene.analysis.Tokenizer
import org.elasticsearch.common.logging.Loggers
import org.elasticsearch.common.settings.Settings
import org.elasticsearch.env.Environment
import org.elasticsearch.index.IndexSettings
import org.elasticsearch.index.analysis.AbstractIndexAnalyzerProvider
import java.io.StringReader

class ProductNameAnalyzerProvider(
    indexSettings: IndexSettings,
    env: Environment,
    name: String,
    settings: Settings
) : AbstractIndexAnalyzerProvider<Analyzer>(name) {

    companion object {
        private val logger = Loggers.getLogger(ProductNameAnalyzerProvider::class.java, "")
        private val contextStore = ContextStore.getStore(ProductNameDictionary.CONTEXT_STORE_KEY)
        private var dictionary: ProductNameDictionary? = null

        @JvmStatic
        fun getAnalyzer(
            str: String,
            useForQuery: Boolean,
            useSynonym: Boolean,
            useStopword: Boolean,
            useFullString: Boolean,
            toUppercase: Boolean
        ): TokenStream {
            val option = AnalyzerOption(useForQuery, useSynonym, useStopword, useFullString, toUppercase)
            val reader = StringReader(str)
            val tokenizer: Tokenizer = ProductNameTokenizer(dictionary, false)
            tokenizer.setReader(reader)
            return ProductNameAnalysisFilter(tokenizer, dictionary, option)
        }
    }

    private val analyzer: Analyzer

    init {
        logger.trace("ProductNameAnalyzerProvider::self {}", this)
        dictionary = if (contextStore.containsKey(ProductNameDictionary.PRODUCT_NAME_DICTIONARY)) {
            contextStore.getAs(ProductNameDictionary.PRODUCT_NAME_DICTIONARY, ProductNameDictionary::class.java)
        } else {
            val dict = ProductNameDictionary.loadDictionary(env)
            if (dict != null) {
                contextStore.put(ProductNameDictionary.PRODUCT_NAME_DICTIONARY, dict)
            }
            dict
        }
        analyzer = ProductNameAnalyzer(dictionary)
    }

    override fun get(): Analyzer {
        logger.trace("ProductNameAnalyzerProvider::get {}", analyzer)
        return analyzer
    }
}

package com.danawa.search.analysis.product

import com.danawa.search.analysis.dict.ProductNameDictionary
import com.danawa.search.analysis.korean.KoreanWordExtractor
import com.danawa.search.analysis.korean.KoreanWordExtractor.ExtractedEntry
import com.danawa.search.analysis.product.TokenTypes.FULL_STRING
import com.danawa.search.analysis.product.TokenTypes.FULL_TERM_LENGTH
import com.danawa.search.analysis.product.TokenTypes.IO_BUFFER_SIZE
import com.danawa.search.analysis.product.TokenTypes.WHITESPACE
import com.danawa.search.analysis.product.TokenTypes.getType
import com.danawa.util.CharVector
import org.apache.lucene.analysis.Tokenizer
import org.apache.lucene.analysis.tokenattributes.CharTermAttribute
import org.apache.lucene.analysis.tokenattributes.OffsetAttribute
import org.apache.lucene.analysis.tokenattributes.TokenInfoAttribute
import org.apache.lucene.analysis.tokenattributes.TypeAttribute
import org.apache.lucene.util.AttributeFactory
import org.elasticsearch.common.logging.Loggers
import java.io.IOException

class ProductNameTokenizer : Tokenizer {

    companion object {
        private val logger = Loggers.getLogger(ProductNameTokenizer::class.java, "")

        // Constants delegated to TokenTypes for Java interop
        @JvmField val DEFAULT_MAX_WORD_LEN = TokenTypes.DEFAULT_MAX_WORD_LEN
        @JvmField val IO_BUFFER_SIZE = TokenTypes.IO_BUFFER_SIZE
        @JvmField val FULL_TERM_LENGTH = TokenTypes.FULL_TERM_LENGTH

        @JvmField val WHITESPACE = TokenTypes.WHITESPACE
        @JvmField val SYMBOL = TokenTypes.SYMBOL
        @JvmField val ALPHA = TokenTypes.ALPHA
        @JvmField val NUMBER = TokenTypes.NUMBER
        @JvmField val HANGUL = TokenTypes.HANGUL
        @JvmField val HANGUL_JAMO = TokenTypes.HANGUL_JAMO
        @JvmField val JAPANESE = TokenTypes.JAPANESE
        @JvmField val CHINESE = TokenTypes.CHINESE
        @JvmField val OTHER_LANGUAGE = TokenTypes.OTHER_LANGUAGE
        @JvmField val UNCATEGORIZED = TokenTypes.UNCATEGORIZED

        @JvmField val NUMBER_TRANS = TokenTypes.NUMBER_TRANS
        @JvmField val MODEL_NAME = TokenTypes.MODEL_NAME
        @JvmField val ALPHANUM = TokenTypes.ALPHANUM
        @JvmField val ASCII = TokenTypes.ASCII
        @JvmField val UNIT = TokenTypes.UNIT
        @JvmField val UNIT_ALPHA = TokenTypes.UNIT_ALPHA
        @JvmField val FULL_STRING = TokenTypes.FULL_STRING
        @JvmField val MAKER = TokenTypes.MAKER
        @JvmField val BRAND = TokenTypes.BRAND
        @JvmField val COMPOUND = TokenTypes.COMPOUND
        @JvmField val STOPWORD = TokenTypes.STOPWORD

        @JvmField val MAX_UNIT_LENGTH = TokenTypes.MAX_UNIT_LENGTH

        @JvmField val AVAIL_SYMBOLS = TokenTypes.AVAIL_SYMBOLS
        @JvmField val AVAIL_SYMBOLS_STANDALONE = TokenTypes.AVAIL_SYMBOLS_STANDALONE
        @JvmField val AVAIL_SYMBOLS_CONNECTOR = TokenTypes.AVAIL_SYMBOLS_CONNECTOR

        @JvmField val SYMBOL_COLON = TokenTypes.SYMBOL_COLON
        @JvmField val PTN_NUMBER = TokenTypes.PTN_NUMBER

        @JvmField val AVAIL_SYMBOLS_INNUMBER = TokenTypes.AVAIL_SYMBOLS_INNUMBER
        @JvmField val AVAIL_SYMBOLS_SPLIT = TokenTypes.AVAIL_SYMBOLS_SPLIT

        // Utility methods delegated to TokenTypes for Java interop
        @JvmStatic
        fun containsChar(array: CharArray, c: Char): Boolean = TokenTypes.containsChar(array, c)

        @JvmStatic
        fun containsChar(array: CharArray, buf: CharArray, length: Int): Boolean = TokenTypes.containsChar(array, buf, length)

        @JvmStatic
        fun isSplit(c: Char): String? = TokenTypes.isSplit(c)

        @JvmStatic
        fun getUniType(cv: CharSequence): String? = TokenTypes.getUniType(cv)

        @JvmStatic
        fun isAlphaNum(cv: CharVector): Boolean = TokenTypes.isAlphaNum(cv)

        @JvmStatic
        fun getTermType(cv: CharSequence): String? = TokenTypes.getTermType(cv)

        @JvmStatic
        fun getType(ch: Int): String = TokenTypes.getType(ch)
    }

    private val termAtt: CharTermAttribute = addAttribute(CharTermAttribute::class.java)
    private val tokenAtt: TokenInfoAttribute = addAttribute(TokenInfoAttribute::class.java)
    private val offsetAtt: OffsetAttribute = addAttribute(OffsetAttribute::class.java)
    private val typeAtt: TypeAttribute = addAttribute(TypeAttribute::class.java)

    private var baseOffset = 0
    private var position = 0
    private var extLength = 0
    private var readLength = 0
    private var tokenLength = 0
    private var finalOffset = 0

    private var buffer: CharArray? = null
    private val backBuffer = arrayOf(CharArray(IO_BUFFER_SIZE), CharArray(IO_BUFFER_SIZE))
    private var entry: ExtractedEntry? = null
    private var extractor: KoreanWordExtractor? = null
    private var chrCurrent: Char = '\u0000'
    private var typeCurrent: String? = null
    private var exportTerm: Boolean = false
    private var tabularFull: Boolean = false

    constructor(dictionary: ProductNameDictionary?, exportTerm: Boolean) : super() {
        if (dictionary != null) {
            extractor = KoreanWordExtractor(dictionary)
            tokenAtt.dictionary(dictionary)
        }
        this.exportTerm = exportTerm
    }

    constructor(factory: AttributeFactory) : super(factory)

    protected fun isTokenChar(c1: Int, c2: Int): Boolean {
        return !Character.isWhitespace(c1)
    }

    @Throws(IOException::class)
    override fun incrementToken(): Boolean {
        typeAtt.setType(null)
        logger.trace("INCREMENT-TOKEN")
        var length = 0
        var start = -1
        var end = -1
        var bufferStart = position
        var continueTerm = false
        var startOffset = 0
        var endOffset = 0
        while (!tokenAtt.isState(TokenInfoAttribute.STATE_INPUT_FINISHED)) {
            if (entry == null) {
                innerLoop@ while (true) {
                    if (position >= readLength) {
                        ////////////////////////////////////////////////////////////////////////////////
                        // 1. 원본 읽어오기 (버퍼 크기만큼 읽어옴)
                        // 읽어온 버퍼가 없거나 모두 처리한 상태라면 리더에서 읽어온다.
                        ////////////////////////////////////////////////////////////////////////////////
                        val oldBuffer = backBuffer[0]
                        val newBuffer = backBuffer[1]
                        backBuffer[0] = newBuffer
                        backBuffer[1] = oldBuffer
                        baseOffset += readLength
                        readLength = input.read(newBuffer, 0, newBuffer.size)
                        logger.trace("READ {}/{}", newBuffer.size, readLength)
                        if (readLength > 0) {
                            buffer = newBuffer
                            tokenAtt.ref(newBuffer, 0, 0)
                            tokenAtt.rmState(TokenInfoAttribute.STATE_INPUT_BUFFER_EXHAUSTED)
                            entry = null
                            tokenLength = readLength
                            while (tokenLength > 0) {
                                if (getType(newBuffer[tokenLength - 1].code) != WHITESPACE) {
                                    break
                                }
                                tokenLength--
                            }
                        } else {
                            readLength = 0
                            logger.trace("LENGTH:{} / {}", length, readLength)
                            if (length > 0) {
                                break
                            } else {
                                finalOffset = correctOffset(baseOffset)
                                logger.trace("TOKENIZER STOPPED!!")
                                tokenAtt.addState(TokenInfoAttribute.STATE_INPUT_FINISHED)
                                return false
                            }
                        }
                        if (tokenLength > 0 && tokenLength < FULL_TERM_LENGTH && baseOffset == 0) {
                            // FULL-TERM. 색인시에는 추출하지 않음 (필터에서 걸러짐)
                            tokenAtt.ref(newBuffer, 0, tokenLength)
                            tokenAtt.posTag(null)
                            offsetAtt.setOffset(0, tokenLength)
                            typeAtt.setType(FULL_STRING)
                            return true
                        }
                        position = 0
                        bufferStart = 0
                        chrCurrent = '\u0000'
                        typeCurrent = null
                    }
                    ////////////////////////////////////////////////////////////////////////////////
                    // 2. 버퍼 내 단순 토크닝 (공백 / 특수기호에 의한 분해)
                    ////////////////////////////////////////////////////////////////////////////////
                    val chrPrev = chrCurrent
                    val typePrev = typeCurrent
                    chrCurrent = buffer!![position]
                    typeCurrent = getType(chrCurrent.code)
                    position++
                    var pass = 1

                    if (typePrev == null) {
                        // 이전문자가 없다면 패스
                    } else if (typePrev == WHITESPACE && typeCurrent != WHITESPACE) {
                        //
                    } else if (typePrev == WHITESPACE && typeCurrent == WHITESPACE) {
                        // 공백뒤 공백. 오프셋 위치 변경
                        pass = 2
                    } else if (typePrev != WHITESPACE && typeCurrent == WHITESPACE) {
                        // 일반문자 뒤 공백. 끊어줌.
                        pass = 0
                    } else if (typePrev != typeCurrent) {
                        // 2021.06.23
                        // 토크닝 수준에서 일부 떨어지고 일부 붙어서 오분석이 나오기 때문에
                        // 모두 떨어뜨려서 한글분석을 거침
                        // 2021.04.26 swsong
                        // 숫자+단위명 조합은 parsingRule에서 다시한번 확인하므로 여기서는 떨어져있어도 무방.
                        // 오히려 v12배터리팩 같은 경우, 한글이 분리가 안되는 부작용이 발생하여 떨어지도록 수정.
                        pass = 0
                    }
                    // logger.trace("CH:{}[{}] / {} / {} / {} / {}", chrCurrent, typeCurrent, typePrev, position, length, pass)
                    if (pass == 1) {
                        // 최초 토크닝 위치 결정
                        if (length == 0) {
                            assert(start == -1)
                            start = baseOffset + position - 1
                            end = start
                        }
                        end++
                        length++
                        // 버퍼 마지막인 경우 무조건 끊어줌 (15키 등)
                        if (position >= tokenLength) {
                            break@innerLoop
                        }
                    } else if (pass == 2) {
                        // 공백 건너뜀
                        bufferStart = position
                        continue@innerLoop
                    } else if (length > 0) {
                        // 토크닝 길이 결정
                        if (position >= tokenLength) {
                            position++
                        }
                        if (typePrev != WHITESPACE && typeCurrent == WHITESPACE) {
                            position--
                        } else if (typePrev != WHITESPACE && typeCurrent != WHITESPACE) {
                            position--
                        }
                        length = position - bufferStart
                        break@innerLoop
                    }
                }

                assert(start != -1)
                startOffset = correctOffset(start)
                endOffset = correctOffset(end)

                if (extractor != null) {
                    logger.trace("TOKEN:{} / {}~{} / {}", CharVector(buffer!!, bufferStart, length), position - bufferStart, length)
                    extLength = length
                    if (extLength > extractor!!.getTabularSize()) {
                        extLength = extractor!!.getTabularSize()
                        tabularFull = true
                    } else {
                        tabularFull = false
                    }
                    logger.trace("EXTRACT:{} / {}~{} / {}", CharVector(buffer!!, bufferStart, extLength), bufferStart, extLength, baseOffset)
                    extractor!!.setInput(buffer!!, bufferStart, extLength)
                    entry = extractor!!.extract()
                    continue
                } else {
                    // 한글분석기가 없는경우 (한글사전 적재 실패) 분해된 토큰으로만 출력
                    tokenAtt.ref(buffer!!, bufferStart, length)
                    offsetAtt.setOffset(startOffset, endOffset.also { finalOffset = it })
                    logger.trace("TOKEN:{} / {}~{}", tokenAtt.ref(), startOffset, endOffset)
                }
            } else {
                while (entry != null) {
                    ////////////////////////////////////////////////////////////////////////////////
                    // 3. 한글분해
                    ////////////////////////////////////////////////////////////////////////////////
                    // 분해된 한글이 있으므로 속성에 출력해 준다
                    if (entry!!.column() <= 0) {
                        entry = entry!!.next()
                        continue
                    }
                    startOffset = correctOffset(baseOffset + entry!!.offset())
                    endOffset = correctOffset(baseOffset + entry!!.offset() + entry!!.column())
                    tokenAtt.ref(buffer!!, entry!!.offset(), entry!!.column())
                    tokenAtt.posTag(entry!!.posTag())
                    offsetAtt.setOffset(startOffset, endOffset)
                    logger.trace("TERM:{} / {}~{} / {} / {} / {}", tokenAtt.ref(), startOffset, endOffset, baseOffset, readLength, tokenAtt.posTag())
                    if (exportTerm) {
                        if (logger.isTraceEnabled) {
                            logger.trace("{} / {}~{}", String(buffer!!, entry!!.offset(), entry!!.column()), entry!!.offset(), entry!!.column())
                        }
                        termAtt.copyBuffer(buffer, entry!!.offset(), entry!!.column())
                    }
                    val extPosition: Int
                    var tempExtPosition = entry!!.offset() + entry!!.column()
                    val prevOffset = entry!!.offset()
                    entry = entry!!.next()
                    // ※ 분석기에서 오분석이 나는경우 (분리어사전 적용시 이전 오프셋으로 되돌아 가는 버그)
                    while (entry != null) {
                        if (entry!!.offset() < prevOffset) {
                            entry = entry!!.next()
                        } else {
                            break
                        }
                    }

                    if (entry == null) {
                        // 분해된 한글이 없다면 다음구간 한글분해 시도
                        if (tempExtPosition < position) {
                            if (tabularFull) {
                                // TabularSize 를 넘어서 분석한 후 경우의 수
                                // 1. 일반적으로 최종 단어와 이후 단어를 이어서 다시한번 단어분석 시도
                                // 2. 분석된 단어길이가 tabularsize 와 같은경우 -> 그대로 출력 (Rule 에서 결합시도)
                                logger.trace("CONTINUE-TERM:{}", tokenAtt.ref())
                                val refLength = tokenAtt.ref()?.length ?: 0
                                if (refLength != extractor!!.getTabularSize()) {
                                    tempExtPosition -= refLength
                                    continueTerm = true
                                }
                            }
                            extLength = position - tempExtPosition
                            if (extLength > extractor!!.getTabularSize()) {
                                extLength = extractor!!.getTabularSize()
                                tabularFull = true
                            } else {
                                tabularFull = false
                            }
                            logger.trace("EXTRACT:{} / {}~{} / {}", CharVector(buffer!!, tempExtPosition, extLength), tempExtPosition, extLength, baseOffset)
                            extractor!!.setInput(buffer!!, tempExtPosition, extLength)
                            entry = extractor!!.extract()
                            if (continueTerm) {
                                continue
                            }
                        }
                    }
                    extPosition = tempExtPosition
                    // 마지막 공백이 있는경우 건너뜀
                    var skipPosition = extPosition
                    while (skipPosition < tokenLength) {
                        if (getType(buffer!![skipPosition].code) != WHITESPACE) {
                            break
                        }
                        skipPosition++
                    }
                    if (skipPosition == tokenLength) {
                        logger.trace("TOKENIZER BUFFER EXHAUSTED!")
                        tokenAtt.addState(TokenInfoAttribute.STATE_INPUT_BUFFER_EXHAUSTED)
                        continue
                    }
                    break
                }
                logger.trace("OFFSET:{} / {} / {} / {}", startOffset, endOffset, position, baseOffset + readLength)
            }
            return true
        }
        return false
    }

    @Throws(IOException::class)
    override fun end() {
        logger.trace("TOKENIZER-END {}", finalOffset)
        super.end()
        offsetAtt.setOffset(finalOffset, finalOffset)
    }

    @Throws(IOException::class)
    override fun reset() {
        logger.trace("TOKENIZER-RESET")
        super.reset()
        position = 0
        extLength = 0
        baseOffset = 0
        readLength = 0
        finalOffset = 0
        tokenLength = 0
        chrCurrent = '\u0000'
        typeCurrent = null
        tabularFull = false
    }

    @Throws(IOException::class)
    override fun close() {
        logger.trace("TOKENIZER-CLOSE")
        super.close()
    }
}

package com.danawa.search.analysis.product

import com.danawa.util.CharVector
import java.util.regex.Pattern

/**
 * Token type constants and utility methods shared between Kotlin and Java code.
 * Extracted from ProductNameTokenizer for mixed compilation compatibility.
 */
object TokenTypes {
    const val DEFAULT_MAX_WORD_LEN = 255
    const val IO_BUFFER_SIZE = 1000
    const val FULL_TERM_LENGTH = 64

    const val WHITESPACE = "<WHITESPACE>"
    const val SYMBOL = "<SYMBOL>"
    const val ALPHA = "<ALPHA>"
    const val NUMBER = "<NUMBER>"
    const val HANGUL = "<HANGUL>"
    const val HANGUL_JAMO = "<HANGUL_JAMO>"
    const val JAPANESE = "<JAPANESE>"
    const val CHINESE = "<CHINESE>"
    const val OTHER_LANGUAGE = "<OTHER_LANGUAGE>"
    const val UNCATEGORIZED = "<UNCATEGORIZED>"

    const val NUMBER_TRANS = "<NUMBER_TRANS>"
    const val MODEL_NAME = "<MODEL_NAME>"
    const val ALPHANUM = "<ALPHANUM>"
    const val ASCII = "<ASCII>"
    const val UNIT = "<UNIT>"
    const val UNIT_ALPHA = "<UNIT_ALPHA>"
    const val FULL_STRING = "<FULL_STRING>"
    const val MAKER = "<MAKER>"
    const val BRAND = "<BRAND>"
    const val COMPOUND = "<COMPOUND>"
    const val STOPWORD = "<STOPWORD>"

    const val MAX_UNIT_LENGTH = 10
    const val SYMBOL_COLON = ':'

    @JvmField
    val AVAIL_SYMBOLS = charArrayOf('-', '.', '/', '+', '&')

    @JvmField
    val AVAIL_SYMBOLS_STANDALONE = charArrayOf()

    @JvmField
    val AVAIL_SYMBOLS_CONNECTOR = charArrayOf('-', '.', '/', '&')

    @JvmField
    val PTN_NUMBER: Pattern = Pattern.compile(
        "^(" +
            "(" +
                "(" +
                    "([0-9]{0,3}([,][0-9]{3})*)" + "|" +
                    "([0-9]+)" +
                ")" +
                "([.][0-9]+)*" +
            ")" +
        ")" +
        "(" +
            "[:]" +
            "(" +
                "(" +
                    "([0-9]{0,3}([,][0-9]{3})*)" + "|" +
                    "([0-9]+)" +
                ")" +
                "([.][0-9]+)*" +
            ")" +
        "){0,1}" +
        "$"
    )

    @JvmField
    val AVAIL_SYMBOLS_INNUMBER = charArrayOf(',', '.', SYMBOL_COLON)

    @JvmField
    val AVAIL_SYMBOLS_SPLIT = charArrayOf(',', '|', '[', ']', '<', '>', '{', '}', '^')

    @JvmStatic
    fun containsChar(array: CharArray, c: Char): Boolean {
        for (ch in array) {
            if (ch == c) return true
        }
        return false
    }

    @JvmStatic
    fun containsChar(array: CharArray, buf: CharArray, length: Int): Boolean {
        for (ch in array) {
            if (!containsChar(array, ch)) return false
        }
        return true
    }

    @JvmStatic
    fun isSplit(c: Char): String? {
        val ret = getType(c.code)
        return when {
            ret == WHITESPACE || ret == SYMBOL -> ret
