package com.danawa.search.util

import org.elasticsearch.action.search.SearchRequest
import org.elasticsearch.common.logging.Loggers
import org.elasticsearch.common.settings.Settings
import org.elasticsearch.core.TimeValue
import org.elasticsearch.index.query.MatchQueryBuilder
import org.elasticsearch.threadpool.ThreadPool
import org.json.JSONObject

import java.io.BufferedReader
import java.io.IOException
import java.io.InputStreamReader
import java.net.HttpURLConnection
import java.net.URL
import java.nio.charset.StandardCharsets
import java.util.Base64

/**
 * ES 9.x 호환 원격 HTTP 클라이언트
 * NodeClient 상속 대신 독립적인 HTTP 기반 검색 클라이언트로 구현
 */
class RemoteNodeClient @JvmOverloads constructor(
    private val settings: Settings,
    private val threadPool: ThreadPool,
    val index: String,
    val host: String,
    val port: Int,
    private val username: String? = null,
    private val password: String? = null
) {
    private val url: String = "http://$host:$port"

    /**
     * 원격 검색 수행 - JSON 응답 반환
     */
    fun search(request: SearchRequest): JSONObject? {
        var co: HttpURLConnection? = null
        var reader: BufferedReader? = null
        try {
            val scroll = request.scroll()?.let { "scroll=${it}" } ?: ""
            logger.info("dictionary Remote Search . {}, username: {}", url, username)

            co = URL("$url/$index/_search?$scroll").openConnection() as HttpURLConnection
            co.requestMethod = "POST"
            co.setRequestProperty("Content-Type", "application/json")
            addAuthHeader(co)
            co.doOutput = true
            co.doInput = true

            co.outputStream.write(request.source().toString().toByteArray(StandardCharsets.UTF_8))
            co.outputStream.flush()

            reader = BufferedReader(InputStreamReader(co.inputStream))
            val sb = StringBuilder()
            reader.forEachLine { sb.append(it) }

            return JSONObject(sb.toString())
        } catch (e: IOException) {
            logger.warn("", e)
            return null
        } finally {
            try { reader?.close() } catch (ignore: Exception) {}
            co?.disconnect()
        }
    }

    /**
     * 스크롤 검색 수행 - JSON 응답 반환
     */
    fun searchScroll(scrollId: String, scrollTime: TimeValue): JSONObject? {
        var co: HttpURLConnection? = null
        var reader: BufferedReader? = null
        try {
            logger.info("dictionary Remote searchScroll . {}, username: {}", url, username)
            val param = """{ "scroll_id":"$scrollId", "scroll":"$scrollTime"}"""
            val paramData = param.toByteArray(StandardCharsets.UTF_8)

            co = URL("$url/_search/scroll").openConnection() as HttpURLConnection
            co.requestMethod = "POST"
            co.setRequestProperty("Content-Type", "application/json")
            addAuthHeader(co)
            co.doInput = true
            co.doOutput = true

            co.outputStream.write(paramData)

            reader = BufferedReader(InputStreamReader(co.inputStream))
            val sb = StringBuilder()
            reader.forEachLine { sb.append(it) }

            return JSONObject(sb.toString())
        } catch (e: IOException) {
            logger.warn("", e)
            return null
        } finally {
            try { reader?.close() } catch (ignore: Exception) {}
            co?.disconnect()
        }
    }

    /**
     * 스크롤 정리
     */
    fun clearScroll(scrollId: String): Boolean {
        var co: HttpURLConnection? = null
        var reader: BufferedReader? = null
        try {
            logger.info("dictionary Remote clearScroll . {}, username: {}", url, username)
            logger.info("clear: {}", scrollId)

            co = URL("$url/_search/scroll/$scrollId").openConnection() as HttpURLConnection
            co.requestMethod = "DELETE"
            co.setRequestProperty("Content-Type", "application/json")
            addAuthHeader(co)
            co.doInput = true

            reader = BufferedReader(InputStreamReader(co.inputStream))
            val sb = StringBuilder()
            reader.forEachLine { sb.append(it) }

            val response = JSONObject(sb.toString())
            return response.optBoolean("succeeded", false)
        } catch (e: IOException) {
            logger.warn("", e)
            return false
        } finally {
            try { reader?.close() } catch (ignore: Exception) {}
            co?.disconnect()
        }
    }

    /**
     * 문서 카운트 조회
     */
    fun count(index: String, matchQuery: MatchQueryBuilder): Long {
        var co: HttpURLConnection? = null
        var reader: BufferedReader? = null
        try {
            logger.info("dictionary Remote count . {}, username: {}", url, username)

            co = URL("$url/$index/_count").openConnection() as HttpURLConnection
            co.requestMethod = "POST"
            co.setRequestProperty("Content-Type", "application/json")
            addAuthHeader(co)
            co.doOutput = true
            co.doInput = true

            co.outputStream.write(matchQuery.toString().toByteArray(StandardCharsets.UTF_8))
            co.outputStream.flush()

            reader = BufferedReader(InputStreamReader(co.inputStream))
            val sb = StringBuilder()
            reader.forEachLine { sb.append(it) }

            val response = JSONObject(sb.toString())
            return response.optLong("count", 0)
        } catch (e: IOException) {
            logger.warn("", e)
            return 0
        } finally {
            try { reader?.close() } catch (ignore: Exception) {}
            co?.disconnect()
        }
    }

    private fun addAuthHeader(co: HttpURLConnection) {
        if (!username.isNullOrEmpty()) {
            val credentials = "$username:$password"
            val token = Base64.getEncoder()
                .encodeToString(credentials.toByteArray(StandardCharsets.UTF_8))
                .replace("==", "")
            co.setRequestProperty("Authorization", "Basic $token")
        }
    }

    companion object {
        private val logger = Loggers.getLogger(RemoteNodeClient::class.java, "")
    }
}

