package com.danawa.search.index

import org.apache.logging.log4j.Logger
import org.elasticsearch.action.bulk.BulkRequestBuilder
import org.elasticsearch.client.internal.node.NodeClient
import org.elasticsearch.common.logging.Loggers

import java.io.BufferedReader
import java.io.File
import java.io.FileFilter
import java.io.FileInputStream
import java.io.InputStreamReader
import java.text.SimpleDateFormat
import java.util.regex.Pattern

/**
 * Bulk text indexer for Elasticsearch.
 * Reads structured text files and indexes them in bulk.
 */
class DanawaBulkTextIndexer(
    private val indexName: String,
    private val path: String,
    private val enc: String,
    private val flush: Int,
    private val client: NodeClient
) : Thread(), FileFilter {

    @Volatile
    private var running: Boolean = false
    private var count: Int = 0
    private var files: MutableList<File> = mutableListOf()

    fun running(): Boolean = running

    fun count(): Int = count

    override fun run() {
        running = true
        count = 0
        files = mutableListOf()

        val paths = path.split(",")
        for (p in paths) {
            val trimmedPath = p.trim()
            val base = File(trimmedPath)
            if (!base.exists()) {
                logger.debug("BASE FILE NOT FOUND : {}", base)
            } else {
                if (base.isDirectory) {
                    base.listFiles(this)
                } else {
                    files.add(base)
                }
            }
        }

        if (files.isNotEmpty()) {
            var reader: BufferedReader? = null
            val time = System.currentTimeMillis()
            var isSourceFile: Boolean

            try {
                var builder: BulkRequestBuilder? = client.prepareBulk()

                for (file in files) {
                    if (!file.exists()) {
                        logger.debug("FILE NOT FOUND : {}", file)
                        continue
                    }
                    isSourceFile = false
                    val istream = FileInputStream(file)
                    reader = BufferedReader(InputStreamReader(istream, enc))
                    logger.debug("PARSING FILE..{}", file)

                    var line: String?
                    while (reader.readLine().also { line = it } != null) {
                        val mat = ptnHead.matcher(line!!)
                        var key: String? = null
                        var offset = 0
                        val source = mutableMapOf<String, Any?>()

                        while (mat.find()) {
                            isSourceFile = true
                            if (key != null) {
                                fieldValue(source, key, line!!.substring(offset, mat.start()))
                            }
                            key = mat.group(1)
                            offset = mat.end()
                        }

                        if (isSourceFile) {
                            fieldValue(source, key!!, line!!.substring(offset))
                            builder?.add(client.prepareIndex(indexName).setSource(source))

                            if (count > 0 && count % flush == 0) {
                                builder?.execute()?.actionGet()
                                builder = client.prepareBulk()
                            }
                            if (count > 0 && count % 100000 == 0) {
                                logger.debug("{} ROWS FLUSHED! in {}ms", count, System.currentTimeMillis() - time)
                            }
                            count++
                        } else {
                            logger.debug("{} IS NOT SOURCEFILE", file)
                            break
                        }
                    }
                    try { reader.close() } catch (_: Exception) { }
                }
                builder?.execute()?.actionGet()
                logger.debug("TOTAL {} ROWS in {}ms", count, System.currentTimeMillis() - time)
            } catch (e: Exception) {
                logger.error("", e)
            } finally {
                try { reader?.close() } catch (_: Exception) { }
            }
        } else {
            logger.debug("THERE'S NO SOURCE FILE(S) FOUND")
        }
        running = false
    }

    @Throws(Exception::class)
    private fun fieldValue(source: MutableMap<String, Any?>, key: String, value: String) {
        when {
            key.isEmpty() -> { }
            key == "REGISTERDATE" -> {
                if (value.isNotEmpty()) {
                    val sdf = SimpleDateFormat("yyyyMMdd")
                    source[key] = sdf.parse(value)
                }
            }
            else -> source[key] = value
        }
        logger.trace("ROW:{} / {}", key, value)
    }

    override fun accept(file: File): Boolean {
        if (!file.exists()) return false
        if (file.isDirectory) {
            file.listFiles(this)
        } else if (file.isFile) {
            files.add(file)
        }
        return false
    }

    companion object {
        private val logger: Logger = Loggers.getLogger(DanawaBulkTextIndexer::class.java, "")
        private val ptnHead: Pattern = Pattern.compile("\\x5b[%]([a-zA-Z0-9_-]+)[%]\\x5d")
    }
}

package com.danawa.search.index

import org.apache.logging.log4j.Logger
import org.elasticsearch.action.bulk.BulkRequestBuilder
import org.elasticsearch.client.internal.node.NodeClient
import org.elasticsearch.common.logging.Loggers
import org.json.JSONObject
import org.json.JSONTokener

import java.io.BufferedReader
import java.io.BufferedWriter
import java.io.File
import java.io.FileOutputStream
import java.io.InputStreamReader
import java.io.OutputStreamWriter
import java.net.HttpURLConnection
import java.net.URL
import java.text.SimpleDateFormat

/**
 * Indexer for migrating data from Fastcat search engine to Elasticsearch.
 * Fetches data via HTTP and indexes into ES.
 */
class FastcatMigrateIndexer(
    url: String,
    start: Int,
    length: Int,
    path: String?,
    enc: String?,
    private val indexName: String,
    private val flush: Int,
    private val client: NodeClient?
) : Thread() {

    private val url: String
    private val start: Int
    private val length: Int
    private val path: String?
    private val enc: String?

    @Volatile
    private var running: Boolean = false
    private var count: Int = 0

    init {
        this.url = url
        this.start = if (start < 1) 1 else start
        this.length = if (length < 10) 10 else length
        this.path = path
        this.enc = if (!path.isNullOrEmpty() && enc.isNullOrEmpty()) "utf-8" else enc
    }

    fun running(): Boolean = running

    fun count(): Int = count

    fun migrateFastcat() {
        var con: HttpURLConnection? = null
        var reader: BufferedReader? = null
        var writer: BufferedWriter? = null
        var builder: BulkRequestBuilder? = null
        val time = System.currentTimeMillis()

        try {
            logger.trace("SEND REQUEST {}", url)
            var total = start + length

            if (!path.isNullOrEmpty()) {
                val file = File(path)
                if (file.parentFile?.exists() == true) {
                    writer = BufferedWriter(OutputStreamWriter(FileOutputStream(file), enc))
                }
            }

            if (client != null) {
                builder = client.prepareBulk()
            }

            var sinx = start
            while (sinx < total) {
                @Suppress("DEPRECATION")
                con = URL("$url&sn=$sinx&ln=$length").openConnection() as HttpURLConnection
                con.requestMethod = "GET"
                val responseCode = con.responseCode
                logger.trace("RESPONSE:{}", responseCode)

                if (responseCode == HttpURLConnection.HTTP_OK) {
                    reader = BufferedReader(InputStreamReader(con.inputStream))
                    val tokener = JSONTokener(reader)
                    val resp = JSONObject(tokener)
                    total = resp.optInt("total_count", total)
                    val fieldNames = resp.optJSONArray("fieldname_list")?.toList() ?: emptyList<Any>()
                    val list = resp.optJSONArray("result")

                    if (list != null) {
                        for (rinx in 0 until list.length()) {
                            val row = list.optJSONObject(rinx)

                            writer?.let { w ->
                                for (key in fieldNames) {
                                    val keyStr = key.toString()
                                    val value = row.getString(keyStr).replace(Regex("[\t\r\n\u0000]"), " ")
                                    w.append("[%").append(keyStr).append("%]").append(value)
                                }
                                w.append(NEWLINE)
                            }

                            builder?.let { b ->
                                b.add(client!!.prepareIndex(indexName).setSource(filterMap(row.toMap())))
                                if (count > 0 && count % flush == 0) {
                                    b.execute().actionGet()
                                    builder = client.prepareBulk()
                                }
                                if (count > 0 && count % 100000 == 0) {
                                    logger.debug("{} ROWS FLUSHED! in {}ms", count, System.currentTimeMillis() - time)
                                }
                            }
                            count++
                        }
                    }
                }
                sinx += length
            }

            builder?.execute()?.actionGet()
            logger.debug("TOTAL {} ROWS in {}ms", count, System.currentTimeMillis() - time)
        } catch (e: Exception) {
            logger.error("", e)
        } finally {
            try { writer?.close() } catch (_: Exception) { }
            try { reader?.close() } catch (_: Exception) { }
        }
    }

    @Throws(Exception::class)
    private fun filterMap(map: Map<String, Any>): MutableMap<String, Any?> {
        val result = map.toMutableMap() as MutableMap<String, Any?>
        for (key in result.keys) {
            fieldValue(result, key, result[key].toString())
        }
        return result
    }

    @Throws(Exception::class)
    private fun fieldValue(source: MutableMap<String, Any?>, key: String, value: String) {
        when {
            key.isEmpty() -> { }
            key == "REGISTERDATE" -> {
                if (value.isNotEmpty()) {
                    val sdf = SimpleDateFormat("yyyyMMdd")
                    source[key] = sdf.parse(value)
                }
            }
            else -> source[key] = value
        }
        logger.trace("ROW:{} / {}", key, value)
    }

    override fun run() {
        running = true
        count = 0
        migrateFastcat()
        running = false
    }

    companion object {
        private val logger: Logger = Loggers.getLogger(FastcatMigrateIndexer::class.java, "")
        private const val NEWLINE = "\r\n"
    }
}

