            index = jparam.optString("index", ES_DICTIONARY_INDEX)
            host = jparam.optString("host", null)
            port = jparam.optInt("port", 9200)
            username = jparam.optString("username", null)
            password = jparam.optString("password", null)
        }

        // Get data from .dsearch_dict_apply index in Map format
        val searchMap = SearchUtil.searchData(client, ".dsearch_dict_apply")

        val remoteNodeClient = RemoteNodeClient(client.settings(), client.threadPool(), ES_DICTIONARY_INDEX, host, port, username, password)

        val productNameDictionary = getDictionary()
        builder
            .key("dictionary").array()
            .`object`()
            .key(ES_DICT_FIELD_TYPE).value("SYSTEM")
            .key("class").value(TagProbDictionary::class.java.simpleName)
            .key("count").value(productNameDictionary?.size() ?: 0)
            .key("label").value(productNameDictionary?.label() ?: "")
            .key("seq").value(productNameDictionary?.seq() ?: 0)
            .key("ignoreCase").value(productNameDictionary?.ignoreCase() ?: true)
            .key("tokenType").value("NONE") // system dictionary has none
            .endObject()
        val dictionaryMap = productNameDictionary?.getDictionaryMap() ?: emptyMap()
        for (key in dictionaryMap.keys) {
            val type = key.uppercase()
            val sourceDictionary = dictionaryMap[key]
            val info = ProductNameDictionary.getDictionaryInfo(sourceDictionary)
            val indexCount: Long = if (!host.isNullOrEmpty()) {
                SearchUtil.count(remoteNodeClient, index, QueryBuilders.matchQuery(ES_DICT_FIELD_TYPE, type))
            } else {
                SearchUtil.count(client, index, QueryBuilders.matchQuery(ES_DICT_FIELD_TYPE, type))
            }

            // Get data from SearchMap and put into each variable
            val id = type.lowercase()
            var count = 0
            var appliedTime = ""
            var updatedTime = ""

            if (searchMap[id] != null) {
                // Applied word count
                count = searchMap[id] as Int
            }
            if (searchMap["${id}_appliedTime"] != null) {
                // Dictionary applied time
                appliedTime = searchMap["${id}_appliedTime"] as String
            }
            if (searchMap["${id}_updatedTime"] != null) {
                // Dictionary data modified time
                updatedTime = searchMap["${id}_updatedTime"] as String
            }

            builder.`object`()
                .key(ES_DICT_FIELD_TYPE).value(type)
                .key("class").value(sourceDictionary?.javaClass?.simpleName)
                .key("dictType").value(sourceDictionary?.type()?.name)
                .key("ignoreCase").value(sourceDictionary?.ignoreCase())
                .key("tokenType").value(sourceDictionary?.tokenType() ?: "NONE")
                .key("label").value(sourceDictionary?.label())
                .key("seq").value(sourceDictionary?.seq())
                .key("id").value(key)
                .key("updatedTime").value(updatedTime) // Time when data was added/deleted/changed in dictionary
                .key("appliedTime").value(appliedTime) // Applied time
                .key("count").value(count) // Applied word count
                .key("indexCount").value(indexCount) // Working word count

            if (info != null && info[1] != 0) {
                builder.key("words").value(info[1])
            }
            builder.endObject()
        }
        builder.endArray()
    }

    /**
     * Search words in dictionary
     */
    private fun findDictionary(request: RestRequest, client: NodeClient, builder: JSONWriter) {
        var jparam = JSONObject()
        var index = request.param("index", ES_DICTIONARY_INDEX)
        var word = request.param("word", "")
        if (GET != request.method()) {
            jparam = parseRequestBody(request)
            index = jparam.optString("index", ES_DICTIONARY_INDEX)
            word = jparam.optString("word", "")
        }

        val productNameDictionary = getDictionary()
        val keySet = productNameDictionary?.getDictionaryMap()?.keys ?: emptySet()

        builder.key("result").array()

        val tagProbs = productNameDictionary?.find(CharVector.valueOf(word))
        if (tagProbs != null) {
            for (inx in tagProbs.indices) {
                val tagProb = tagProbs[inx]
                builder.`object`()
                    .key(ES_DICT_FIELD_TYPE).value("SYSTEM")
                    .key(ES_DICT_FIELD_KEYWORD).value(word)
                    .key("posTag").value(tagProb.posTag())
                    .key("prob").value(tagProb.prob())
                    .endObject()
            }
        }
        for (type in keySet) {
            val typeUpper = type.uppercase()

            val query: BoolQueryBuilder = QueryBuilders.boolQuery()
                .must(QueryBuilders.matchQuery(ES_DICT_FIELD_TYPE, typeUpper))
                .must(
                    QueryBuilders.boolQuery()
                        .should(QueryBuilders.matchQuery(ES_DICT_FIELD_KEYWORD, word))
                        .should(QueryBuilders.matchQuery(ES_DICT_FIELD_VALUE, word))
                )
            val result = SearchUtil.search(client, index, query, null, null, 0, -1, true, null)
            while (result != null && result.hasNext()) {
                val data = result.next()
                val keyword = CharVector.valueOf(data[ES_DICT_FIELD_KEYWORD])
                val value = CharVector.valueOf(data[ES_DICT_FIELD_VALUE])
                val id = CharVector.valueOf(data[ES_DICT_FIELD_ID])
                builder.`object`()
                builder.key(ES_DICT_FIELD_TYPE).value(typeUpper)
                if (keyword != null && keyword.length > 0) {
                    builder.key(ES_DICT_FIELD_KEYWORD).value(keyword)
                }
                if (value != null && value.length > 0) {
                    builder.key(ES_DICT_FIELD_VALUE).value(value)
                }
                if (id != null && id.length > 0) {
                    builder.key(ES_DICT_FIELD_ID).value(id)
                }
                builder.endObject()
            }
        }
        builder.endArray()
    }

    /**
     * Restore compiled binary dictionary -> ES index data
     */
    private fun restoreDictionary(request: RestRequest, client: NodeClient) {
        var jparam = JSONObject()
        var index = request.param("index", ES_DICTIONARY_INDEX)
        if (GET != request.method()) {
            jparam = parseRequestBody(request)
            index = jparam.optString("index", ES_DICTIONARY_INDEX)
        }

        SearchUtil.deleteAllData(client, index)
        val repo = DictionarySource(client, index)
        ProductNameDictionary.restoreDictionary(repo, index)
    }

    /**
     * Danawa product text data -> ES index execution
     */
    private fun bulkIndex(request: RestRequest, client: NodeClient): Int {
        var ret = 0
        var jparam = JSONObject()
        var index = request.param("index", "")
        var path = request.param("path", "")
        var enc = request.param("enc", "euc-kr")
        var flush = request.paramAsInt("flush", 50000)
        if (GET != request.method()) {
            jparam = parseRequestBody(request)
            index = jparam.optString("index", "")
            path = jparam.optString("path", "")
            enc = jparam.optString("enc", "euc-kr")
            flush = jparam.optInt("flush", 50000)
        }

        synchronized(this) {
            if (indexingThread == null || indexingThread?.running() != true) {
                indexingThread = DanawaBulkTextIndexer(index, path, enc, flush, client)
                indexingThread?.start()
            } else {
                ret = indexingThread?.count() ?: 0
            }
        }
        return ret
    }

    /**
     * Danawa product FASTCAT -> ES index execution
     */
    private fun fastcatIndex(request: RestRequest, client: NodeClient): Int {
        var ret = 0
        var jparam = JSONObject()
        var url = request.param("url", "")
        var start = request.paramAsInt("start", 1)
        var length = request.paramAsInt("length", 1000)
        var path = request.param("path", "")
        var enc = request.param("enc", "euc-kr")
        var index = request.param("index", "")
        var flush = request.paramAsInt("flush", 50000)
        try {
            url = URLDecoder.decode(url, "utf-8")
        } catch (ignore: Exception) { }
        if (GET != request.method()) {
            jparam = parseRequestBody(request)
            url = jparam.optString("url", "")
            start = jparam.optInt("start", 1)
            length = jparam.optInt("length", 1000)
            path = jparam.optString("path", "")
            enc = jparam.optString("enc", "euc-kr")
            index = jparam.optString("index", "")
            flush = jparam.optInt("flush", 50000)
        }

        synchronized(this) {
            if (migratingThread == null || migratingThread?.running() != true) {
                migratingThread = FastcatMigrateIndexer(url, start, length, path, enc, index, flush, client)
                migratingThread?.start()
            } else {
                ret = migratingThread?.count() ?: 0
            }
        }
        return ret
    }

    /**
     * Search using product name analyzer
     */
    private fun search(request: RestRequest, client: NodeClient, builder: JSONWriter) {
        var jparam = JSONObject()
        var index = request.param("index", "")
        var fields = request.param("fields", "").split(",").toTypedArray()
        val boostMap = mutableMapOf<String, Float>()
        var text = request.param("text", "")
        var queryString: String? = request.param("query", "")
        var totalIndex = request.param("totalIndex", ES_INDEX_TOTALINDEX)
        var from = request.paramAsInt("from", 0)
        var size = request.paramAsInt("size", 20)
        var showTotal = request.paramAsBoolean("showTotal", false)
        var showExplain = request.paramAsBoolean("showExplain", false)
        var showDetail = request.paramAsBoolean("showDetail", false)
        var useScroll = request.paramAsBoolean("useScroll", false)
        var sortStr: String? = request.param("sort")
        var highlightStr: String? = request.param("highlight")
        var analyzer = request.param("analyzer", "whitespace")
        if (GET != request.method()) {
            jparam = parseRequestBody(request)
            index = jparam.optString("index", "")
            fields = jparam.optString("fields", "").split(",").toTypedArray()
            text = jparam.optString("text", "")
            queryString = jparam.optString("query", "")
            totalIndex = jparam.optString("totalIndex", ES_INDEX_TOTALINDEX)
            from = jparam.optInt("from", 0)
            size = jparam.optInt("size", 20)
            showTotal = jparam.optBoolean("showTotal", false)
            showExplain = jparam.optBoolean("showExplain", false)
            showDetail = jparam.optBoolean("showDetail", false)
            useScroll = jparam.optBoolean("useScroll", false)
            sortStr = jparam.optString("sort")
            highlightStr = jparam.optString("highlight")
            analyzer = jparam.optString("analyzer", "whitespace")
        }

        for (inx in fields.indices) {
            val item = fields[inx].split("[\\^]".toRegex()).toTypedArray()
            val field = item[0].trim()
            if (item.size > 1) {
                var boost = 1.0f
                try {
                    boost = item[1].trim().toFloat()
                } catch (ignore: Exception) { }
                boostMap[field] = boost
            }
            fields[inx] = field
        }

        var stream: TokenStream? = null
        try {
            logger.trace("ANALYZE TEXT : {}", text)
            stream = ProductNameAnalyzerProvider.getAnalyzer(text, true, true, true, true, false)
            var explain: JSONObject? = null
            if (showExplain) {
                explain = JSONObject()
            }

            var sortSet: List<SortBuilder<*>>? = null
            if (!sortStr.isNullOrEmpty()) {
                logger.trace("SORT:{}", sortStr)
                sortSet = DanawaSearchQueryBuilder.parseSortSet(sortStr)
            }

            var highlight: HighlightBuilder? = null
            val views = mutableListOf<String>()
            val highlightTags = mutableListOf<String>()
            if (!highlightStr.isNullOrEmpty()) {
                logger.trace("HIGHLIGHT:{}", highlightStr)
                highlight = DanawaSearchQueryBuilder.parseHighlight(highlightStr)
                val preTags = highlight.preTags()
                val postTags = highlight.postTags()
                if (preTags != null && postTags != null && preTags.isNotEmpty() && postTags.isNotEmpty()) {
                    highlightTags.add(preTags[0])
                    highlightTags.add(postTags[0])
                }
                for (field in highlight.fields()) {
                    val name = field.name()
                    logger.trace("FIELD:{}", name)
                    if ("_all" != name) {
                        views.add(name)
                    }
                }
            }

            val highlightTerms = mutableListOf<String>()
            var query: QueryBuilder = DanawaSearchQueryBuilder.buildAnalyzedQuery(stream, fields, totalIndex, boostMap, views, highlightTerms, explain, analyzer)
            if (!queryString.isNullOrEmpty()) {
                try {
                    val baseQuery = DanawaSearchQueryBuilder.parseQuery(queryString)
                    logger.trace("Q:{}", baseQuery)
                    if (baseQuery is FunctionScoreQueryBuilder) {
                        val innerQuery = baseQuery.query()
                        if (innerQuery is BoolQueryBuilder) {
                            innerQuery.must().clear()
                            innerQuery.must(query)
                            logger.trace("Q:{}", innerQuery)
                        }
                        query = baseQuery
                    }
                } catch (e: Exception) {
                    logger.error("", e)
                }
            }
            logger.trace("Q:{}", query)
            var total: Long = -1
            if (showTotal) {
                total = SearchUtil.count(client, index, query)
            }

            val doScroll = if (!useScroll) false else from + size > 10000
            builder.`object`()
            if (showExplain) {
                builder.key("explain").value(explain)
            }
            if (showDetail) {
                builder.key("detail").value(JSONObject(query.toString()))
            }
            if (total != -1L) {
                builder.key("total").value(total)
            }
            builder.key("result").array()

            val dataModifier = object : DataModifier {
                override fun modify(map: MutableMap<String, Any>) {
                    for (field in views) {
                        if (map.containsKey(field)) {
                            val obj = map[field]
                            if (obj is String) {
                                map[field] = SearchUtil.highlightString(obj, highlightTerms, highlightTags)
                            }
                        }
                    }
                }
            }
            val iter = SearchUtil.search(client, index, query, sortSet, highlight, from, size, doScroll, dataModifier)
            while (iter != null && iter.hasNext()) {
                val map = iter.next()
                builder.`object`()
                for (key in map.keys) {
                    builder.key(key).value(map[key])
                }
                builder.endObject()
            }
            builder.endArray()
            builder.endObject()
        } catch (e: Exception) {
            logger.error("", e)
        } finally {
            try { stream?.close() } catch (ignore: Exception) { }
        }
    }

    /**
     * Build search query using product name analyzer
     */
    private fun buildQuery(request: RestRequest, client: NodeClient, builder: JSONWriter) {
        var jparam = JSONObject()
        var fields = request.param("fields", "").split(",").toTypedArray()
        var totalIndex = request.param("totalIndex", ES_INDEX_TOTALINDEX)
        var text = request.param("text", "")
        var analyzer = request.param("analyzer", "whitespace")
        if (GET != request.method()) {
            jparam = parseRequestBody(request)
            fields = jparam.optString("fields", "").split(",").toTypedArray()
            totalIndex = jparam.optString("totalIndex", ES_INDEX_TOTALINDEX)
            text = jparam.optString("text", "")
            analyzer = jparam.optString("analyzer", "whitespace")
        }
        var stream: TokenStream? = null
        try {
            logger.trace("ANALYZE TEXT : {}", text)
            stream = ProductNameAnalyzerProvider.getAnalyzer(text, true, true, true, true, false)
            val query = DanawaSearchQueryBuilder.buildAnalyzedJSONQuery(stream, fields, totalIndex, analyzer)
            builder.`object`()
                .key("query").value(query)
                .endObject()
        } catch (e: Exception) {
            logger.error("", e)
        } finally {
            try { stream?.close() } catch (ignore: Exception) { }
        }
    }

    private fun makeSearchKeyword(request: RestRequest, client: NodeClient, writer: JSONWriter) {
        var jparam = JSONObject()
        var index = request.param("index", ES_DICTIONARY_INDEX)
        var text = request.param("text", "")
        var stopWord = request.paramAsBoolean("stopWord", true)
        var synonym = request.paramAsBoolean("synonym", true)

        if (GET != request.method()) {
            jparam = parseRequestBody(request)
            index = jparam.optString("index", ES_DICTIONARY_INDEX)
            text = jparam.optString("text", "")
            stopWord = jparam.optBoolean("stopWord", true)
            synonym = jparam.optBoolean("synonym", true)
        }

        var stream: TokenStream? = null
        try {
            stream = ProductNameAnalyzerProvider.getAnalyzer(text, true, synonym, stopWord, true, false)
            expansionKeyword(text, stream, writer)
        } finally {
            try { stream?.close() } catch (ignore: Exception) { }
        }
    }

    private fun getSynonymListAction(request: RestRequest, client: NodeClient, writer: JSONWriter) {
        var jparam = JSONObject()
        var keyword = ""
        val useForQuery = true
        val useSynonym = true
        val useStopword = false
        val useFullString = true

        logger.debug("get-synonym-list start")
        if (GET != request.method()) {
            jparam = parseRequestBody(request)
            keyword = jparam.optString("keyword", "")
        } else {
            try {
                keyword = URLDecoder.decode(request.param("keyword", ""), "UTF-8")
            } catch (e: Exception) {
                logger.error("UnsupportedEncodingException Catched !!! >>>> \n" + e.message)
                logger.debug("error >>> {}", e)
            }
        }

        var stream: TokenStream? = null
        try {
            writer.key("query").value(keyword)
            writer.key("result").array()
            stream = ProductNameAnalyzerProvider.getAnalyzer(keyword, useForQuery, useSynonym, useStopword, useFullString, false)
            getSynonymList(keyword, stream, writer)
            writer.endArray()
            writer.key("success").value(true)
        } finally {
            try {
                stream?.close()
            } catch (ignore: Exception) {
                logger.debug("Exception >>> {}", ignore.message)
            }
        }
    }

    /**
     * ES dictionary index query class
     * Used for dictionary compilation, etc.
     */
    class DictionarySource : DictionaryRepository, Iterator<Array<CharSequence?>> {
        private var client: Client? = null
        private var remoteClient: RemoteNodeClient? = null
        private val index: String
        private var iterator: Iterator<Map<String, Any>>? = null
        private var remoteResults: MutableList<Map<String, Any>>? = null
        private var remoteIndex: Int = 0

        constructor(client: Client, index: String) {
            this.client = client
            this.index = index
        }

        constructor(remoteClient: RemoteNodeClient, index: String) {
            this.remoteClient = remoteClient
            this.index = index
        }

        override fun getSource(type: String): Iterator<Array<CharSequence?>> {
            try {
                val query: QueryBuilder = QueryBuilders.matchQuery(ES_DICT_FIELD_TYPE, type.uppercase())
                logger.trace("QUERY:{}", query)

                if (remoteClient != null) {
                    // Remote search using RemoteNodeClient
                    remoteResults = mutableListOf()
                    remoteIndex = 0
                    val searchRequest = org.elasticsearch.action.search.SearchRequest()
                    val sourceBuilder = org.elasticsearch.search.builder.SearchSourceBuilder()
                    sourceBuilder.query(query).size(10000)
                    searchRequest.indices(index).source(sourceBuilder)

                    val response = remoteClient!!.search(searchRequest)
                    if (response != null && response.has("hits")) {
                        val hits = response.getJSONObject("hits")
                        val hitsArray = hits.getJSONArray("hits")
                        for (i in 0 until hitsArray.length()) {
                            val hit = hitsArray.getJSONObject(i)
                            val source = hit.getJSONObject("_source")
                            val map = mutableMapOf<String, Any>()
                            for (key in source.keySet()) {
                                map[key] = source.get(key)
                            }
                            remoteResults!!.add(map)
                        }
                    }
                } else {
                    // Search using local Client
                    iterator = SearchUtil.search(client, index, query, null, null, 0, -1, true, null)
                }
            } catch (e: Exception) {
                logger.error("", e)
            }
            return this
        }

        override fun restore(type: String, ignoreCase: Boolean, wordSet: Set<CharSequence>) {
            if (client == null) {
                logger.warn("restore() is not supported for RemoteNodeClient")
                return
            }
            var source: MutableMap<String, Any>?
            var builder: BulkRequestBuilder?
            try {
                builder = client!!.prepareBulk()
                var inx = 0
                for (data in wordSet) {
                    val words = data.toString().split(TAB)
                    source = mutableMapOf()
                    source[ES_DICT_FIELD_TYPE] = type.uppercase()
                    when {
                        words.size == 1 -> {
                            source[ES_DICT_FIELD_KEYWORD] = words[0]
                        }
                        words.size == 2 -> {
                            if (words[0].isNotEmpty()) {
                                source[ES_DICT_FIELD_KEYWORD] = words[0]
                            }
                            source[ES_DICT_FIELD_VALUE] = words[1]
                        }
                        else -> {
                            source[ES_DICT_FIELD_KEYWORD] = words[0]
                            source[ES_DICT_FIELD_VALUE] = words[1]
                            source[ES_DICT_FIELD_ID] = words[2]
                        }
                    }
                    builder.add(client!!.prepareIndex(index).setSource(source))
                    if (inx > 0 && inx % 1000 == 0) {
                        builder.execute().actionGet()
                        builder = client!!.prepareBulk()
                    }
                    inx++
                }
                if (inx > 0) {
                    builder.execute().actionGet()
                }
            } catch (e: Exception) {
                logger.error("", e)
            }
        }

        override fun hasNext(): Boolean {
            return if (remoteClient != null) {
                remoteResults != null && remoteIndex < remoteResults!!.size
            } else {
                iterator != null && iterator!!.hasNext()
            }
        }

        override fun next(): Array<CharSequence?> {
            val data: Map<String, Any> = if (remoteClient != null) {
                remoteResults!![remoteIndex++]
            } else {
                iterator!!.next()
            }
            val id = CharVector.valueOf(data[ES_DICT_FIELD_ID])
            val keyword = CharVector.valueOf(data[ES_DICT_FIELD_KEYWORD])
            val value = CharVector.valueOf(data[ES_DICT_FIELD_VALUE])
            return arrayOf(id, keyword, value)
        }

        override fun close() { }
    }
}

