   108→			search.scroll(DEFAULT_SCROLL_KEEP_ALIVE);
   109→			SearchResponse response = client.search(search).get();
   110→			hits = response.getHits().getHits();
   111→			scrollId = response.getScrollId();
   112→			clearScroll.addScrollId(scrollId);
   113→
   114→			int totInx = 0;
   115→			for (; hits != null && hits.length > 0;) {
   116→				for (int inx = 0; inx < hits.length; inx++, totInx++) {
   117→					DeleteRequest request = new DeleteRequest(index, hits[inx].getId());
   118→					builder.add(request);
   119→					if (totInx > 0 && totInx % 5000 == 0) {
   120→						builder.execute().actionGet();
   121→						builder = client.prepareBulk();
   122→					}
   123→				}
   124→				SearchScrollRequest scrollRequest = new SearchScrollRequest(scrollId);
   125→				scrollRequest.scroll(DEFAULT_SCROLL_KEEP_ALIVE);
   126→				response = client.searchScroll(scrollRequest).get();
   127→				hits = response.getHits().getHits();
   128→				scrollId = response.getScrollId();
   129→				clearScroll.addScrollId(scrollId);
   130→			}
   131→			if (totInx > 0) {
   132→				builder.execute().actionGet();
   133→			}
