   323→	static class ScrollSearchResultIterator extends AbstractSearchResultIterator {
   324→
   325→		private Client client;
   326→		private SearchHit[] hits;
   327→		private ClearScrollRequest clearScroll;
   328→		private String scrollId;
   329→		private int rowNum;
