   337→
   338→		public ScrollSearchResultIterator() {
   339→			this(DEFAULT_SEARCH_TIME_OUT, DEFAULT_SCROLL_KEEP_ALIVE, DEFAULT_SCROLL_SIZE);
   340→		}
   341→
   342→		public ScrollSearchResultIterator(TimeValue timeOut, TimeValue scrollKeepAlive, int scrollSize) {
   343→			this.scrollKeepAlive = scrollKeepAlive;
   344→			this.timeOut = timeOut;
   345→			this.scrollSize = scrollSize;
   346→		}
