            .must(
                QueryBuilders.boolQuery()
                    .should(QueryBuilders.matchQuery(ES_DICT_FIELD_KEYWORD, word))
                    .should(QueryBuilders.matchQuery(ES_DICT_FIELD_VALUE, word))
            )
        val resultIter = SearchUtil.search(client, index, query, null, null, 0, -1, true, null)
        while (resultIter != null && resultIter.hasNext()) {
            val data = resultIter.next()
            val keyword = CharVector.valueOf(data[ES_DICT_FIELD_KEYWORD])
            val value = CharVector.valueOf(data[ES_DICT_FIELD_VALUE])
            val id = CharVector.valueOf(data[ES_DICT_FIELD_ID])
            builder.`object`()
            builder.key(ES_DICT_FIELD_TYPE).value(typeUpper)
            if (keyword != null && keyword.length > 0) {
                builder.key(ES_DICT_FIELD_KEYWORD).value(keyword)
            }
            if (value != null && value.length > 0) {
                builder.key(ES_DICT_FIELD_VALUE).value(value)
            }
            if (id != null && id.length > 0) {
                builder.key(ES_DICT_FIELD_ID).value(id)
            }
            builder.endObject()
        }
    }
    builder.endArray()
}

/**
 * Restore compiled binary dictionary -> ES index data
 */
private fun restoreDictionary(request: RestRequest, client: NodeClient) {
    var jparam = JSONObject()
    var index = request.param("index", ES_DICTIONARY_INDEX)
    if (GET != request.method()) {
        jparam = parseRequestBody(request)
        index = jparam.optString("index", ES_DICTIONARY_INDEX)
    }

    SearchUtil.deleteAllData(client, index)
    val repo = DictionarySource(client, index)
    ProductNameDictionary.restoreDictionary(repo, index)
}

/**
 * Danawa product text data -> ES index execution
 */
private fun bulkIndex(request: RestRequest, client: NodeClient): Int {
    var ret = 0
    var jparam = JSONObject()
    var index = request.param("index", "")
    var path = request.param("path", "")
    var enc = request.param("enc", "euc-kr")
    var flush = request.paramAsInt("flush", 50000)
    if (GET != request.method()) {
        jparam = parseRequestBody(request)
        index = jparam.optString("index", "")
        path = jparam.optString("path", "")
        enc = jparam.optString("enc", "euc-kr")
        flush = jparam.optInt("flush", 50000)
    }

    synchronized(this) {
        if (indexingThread == null || indexingThread?.running() != true) {
            indexingThread = DanawaBulkTextIndexer(index, path, enc, flush, client)
            indexingThread?.start()
        } else {
            ret = indexingThread?.count() ?: 0
        }
    }
    return ret
}

