class ProductNameAnalysisAction : BaseRestHandler() {

    companion object {
        private val logger: Logger = Loggers.getLogger(ProductNameAnalysisAction::class.java, "")

        // Plugin global context store
        private val contextStore: ContextStore = ContextStore.getStore(ProductNameDictionary.CONTEXT_STORE_KEY)

        private const val CONTENT_TYPE_JSON = "application/json;charset=UTF-8"
        private const val BASE_URI = "/_analysis-product-name"
        private const val ACTION_TEST = "test"
        private const val ACTION_INFO_DICT = "info-dict"
        private const val ACTION_FIND_DICT = "find-dict"
        private const val ACTION_RELOAD_DICT = "reload-dict"
        private const val ACTION_RESTORE_DICT = "restore-dict"
        private const val ACTION_COMPILE_DICT = "compile-dict"
        private const val ACTION_FULL_INDEX = "full-index"
        private const val ACTION_FASTCAT_INDEX = "fastcat-index"
        private const val ACTION_ANALYZE_TEXT = "analyze"
        private const val ACTION_SEARCH = "search"
        private const val ACTION_BUILD_QUERY = "build-query"
        private const val ACTION_SYNONYM_LIST = "get-synonym-list"
        private const val ACTION_ANALYZE_MULTI_PARAMS = "multi-analyze"
        private const val ACTION_SEARCH_KEYWORD = "search-keyword"
        private const val ACTION_CHECK_ENABLE = "check-dict"

        private const val ES_DICTIONARY_INDEX = ".dsearch_dict"
        private const val ES_DICT_FIELD_ID = "id"
        private const val ES_DICT_FIELD_TYPE = "type"
        private const val ES_DICT_FIELD_KEYWORD = "keyword"
        private const val ES_DICT_FIELD_VALUE = "value"
        private const val ES_INDEX_TOTALINDEX = "TOTALINDEX"

        private const val TAG_BR = "<br/>"
        private const val TAG_STRONG = "<strong>\${TEXT}</strong>"
        private const val REGEX_TAG_TEXT = "[$][{]TEXT[}]"
        private const val COMMA = ","
        private const val TAB = "\t"

        private const val ANALYZE_SET_FULL_STRING = "00_FULL_STRING_SET"
        private const val ANALYZE_SET_STOPWORD = "01_RESTRICTED_SET"
        private const val ANALYZE_SET_MODEL_NAME = "02_MODEL_NAME_SET"
        private const val ANALYZE_SET_UNIT = "03_UNIT_SET"
        private const val ANALYZE_SET_NORMAL = "04_NORMAL_SET"
        private const val ANALYZE_SET_SYNONYM = "05_SYNONYM_SET"
        private const val ANALYZE_SET_COMPOUND = "06_COMPOUND_SET"
        private const val ANALYZE_SET_FINAL = "07_FINAL_SET"

        /**
         * Text detailed analysis result classification
         */
        private val ANALYSIS_RESULT_LABELS: Map<String, String> = mapOf(
            ANALYZE_SET_FULL_STRING to "전체질의어",
            ANALYZE_SET_STOPWORD to "불용어",
            ANALYZE_SET_MODEL_NAME to "모델명 규칙",
            ANALYZE_SET_UNIT to "단위명 규칙",
            ANALYZE_SET_NORMAL to "형태소 분리 결과",
            ANALYZE_SET_SYNONYM to "동의어 확장",
            ANALYZE_SET_COMPOUND to "복합명사",
            ANALYZE_SET_FINAL to "최종 결과"
        )

        /**
         * Check if synonym is one-way
         */
        @JvmStatic
        fun isOneWaySynonym(client: NodeClient?, index: String?, word: String): Boolean {
            var ret = false
            // One-way determination
            if (client != null && !index.isNullOrEmpty()) {
                // When using index
                val query: BoolQueryBuilder = QueryBuilders.boolQuery()
                    .must(QueryBuilders.matchQuery(ES_DICT_FIELD_TYPE, ProductNameDictionary.DICT_SYNONYM.uppercase()))
                    .must(QueryBuilders.matchQuery(ES_DICT_FIELD_KEYWORD, word))
                logger.trace("Q:{}", query)
                val count = SearchUtil.count(client, index, query)
                if (count > 0) {
                    ret = true
                }
                logger.trace("SYNONYM:{}-{} = {}", index, word, count)
            } else {
                // When using memory dictionary
                val dictionary = getDictionary()
                val synonyms = dictionary?.getDictionary(ProductNameDictionary.DICT_SYNONYM, SynonymDictionary::class.java)
                if (synonyms != null) {
                    ret = ProductNameDictionary.isOneWaySynonym(CharVector.valueOf(word) as CharSequence, synonyms.map())
                }
            }
            return ret
        }

        /**
         * Product name detailed analysis.
         * Analyzes text through analyzer and outputs it.
         * Created in a format suitable for Danawa management module.
         */
        @JvmStatic
        fun analyzeTextDetail(
            client: NodeClient?,
            text: String,
            stream: TokenStream,
            index: String?,
            result: MutableMap<String, MutableList<MutableList<String>>>,
            synonymWayMap: MutableMap<String, Boolean>,
            synonymMap: MutableMap<String, MutableList<String>>,
            useForQuery: Boolean
        ) {
            val termAttr = stream.addAttribute(CharTermAttribute::class.java)
            val typeAttr = stream.addAttribute(TypeAttribute::class.java)
            val extAttr = stream.addAttribute(ExtraTermAttribute::class.java)
            val synAttr = stream.addAttribute(SynonymAttribute::class.java)
            val offAttr = stream.addAttribute(OffsetAttribute::class.java)
            var wordList: MutableList<MutableList<String>>?
            var words: MutableList<String>?
            var words2: MutableList<String>?
            var syns: List<CharSequence>? = synAttr.getSynonyms()
            val tempTermList = mutableListOf<String>()

            for (key in ANALYSIS_RESULT_LABELS.keys) {
                result[key] = mutableListOf()
            }

            var term: String
            var type: String?
            var setName: String? = null
            var setNamePrev: String?
            var offset = intArrayOf(0, 0)
            var offsetPrev: IntArray
            var oneWaySynonym: Boolean

            // Synonym expansion for more than 2 terms
            var prevTerm: String? = null
            var prePrevTerm: String? = null
            val dictionary = getDictionary()
            val synonymDict = dictionary?.getDictionary(ProductNameDictionary.DICT_SYNONYM, SynonymDictionary::class.java)

            try {
                stream.reset()
                while (stream.incrementToken()) {
                    setNamePrev = setName
                    offsetPrev = intArrayOf(offset[0], offset[1])
                    term = termAttr.toString()
                    type = typeAttr.type()
                    offset = intArrayOf(offAttr.startOffset(), offAttr.endOffset())
                    logger.trace("TERM:{} / {}", term, type)

                    when {
                        ANALYZE_SET_FULL_STRING != setNamePrev && offset[0] < offsetPrev[1] -> {
                            // Sub-word after model name / unit name (at indexing time)
                            wordList = result[setNamePrev]
                            if (wordList != null && wordList.isNotEmpty()) {
                                words = wordList[wordList.size - 1]
                                words.add(term)
                                setName = setNamePrev
                                offset = intArrayOf(offsetPrev[0], offsetPrev[1])
                                setAnalyzedResult(result, term, ANALYZE_SET_NORMAL, ANALYZE_SET_FINAL)
                            }
                        }
                        TokenTypes.FULL_STRING == type -> {
                            // Full term
                            setName = ANALYZE_SET_FULL_STRING
                            setAnalyzedResult(result, term, ANALYZE_SET_FULL_STRING, ANALYZE_SET_FINAL)
                        }
                        TokenTypes.MODEL_NAME == type -> {
                            // Model name extraction differs between indexing and query time
                            setName = ANALYZE_SET_MODEL_NAME
                            setAnalyzedResult(result, term, ANALYZE_SET_MODEL_NAME, ANALYZE_SET_NORMAL, ANALYZE_SET_FINAL)
                        }
                        TokenTypes.UNIT == type -> {
                            // Unit name
                            setName = ANALYZE_SET_UNIT
                            setAnalyzedResult(result, term, ANALYZE_SET_UNIT, ANALYZE_SET_NORMAL, ANALYZE_SET_FINAL)
                        }
                        TokenTypes.COMPOUND == type -> {
                            setName = ANALYZE_SET_COMPOUND
                            setAnalyzedResult(result, term, ANALYZE_SET_COMPOUND, ANALYZE_SET_NORMAL, ANALYZE_SET_FINAL)
                        }
                        TokenTypes.STOPWORD == type -> {
                            setName = ANALYZE_SET_STOPWORD
                            setAnalyzedResult(result, term, ANALYZE_SET_STOPWORD)
                        }
                        else -> {
                            // Normal word
                            setName = ANALYZE_SET_NORMAL
                            setAnalyzedResult(result, term, ANALYZE_SET_NORMAL, ANALYZE_SET_FINAL)
                        }
                    }

                    syns = synAttr.getSynonyms()
                    if (syns != null && syns.isNotEmpty()) {
                        wordList = result[ANALYZE_SET_SYNONYM]
                        words = mutableListOf()
                        wordList?.add(words)
                        words.add(term)
                        wordList = result[setName]
                        words2 = if (wordList != null && wordList.isNotEmpty()) wordList[wordList.size - 1] else null
                        oneWaySynonym = isOneWaySynonym(client, index, term)
                        synonymWayMap[term] = oneWaySynonym
                        synonymMap[term] = words
                        logger.trace("SYNONYM [{}] {} / {} / {}", setName, term, oneWaySynonym, syns)
                        for (synonym in syns) {
                            val s = synonym.toString()
                            words.add(s)
                            if (ANALYZE_SET_NORMAL != setName && ANALYZE_SET_MODEL_NAME != setName) {
                                words2?.add(s)
                            }
                            setAnalyzedResult(result, s, ANALYZE_SET_FINAL)
                        }
                    }

                    if (ANALYZE_SET_FULL_STRING != setName) {
                        val iter = extAttr.iterator()
                        if (iter != null && iter.hasNext()) {
                            wordList = result[setName]
                            words = if (wordList != null && wordList.isNotEmpty()) wordList[wordList.size - 1] else null
                            while (iter.hasNext()) {
                                val s = iter.next()
                                logger.trace("EXT [{}] {} / {} / {} / {}", setName, term, s, words, wordList)
                                words?.add(s)
                                setAnalyzedResult(result, s, ANALYZE_SET_NORMAL, ANALYZE_SET_FINAL)
                                syns = synAttr.getSynonyms()
                                if (syns != null && syns.isNotEmpty()) {
                                    oneWaySynonym = isOneWaySynonym(client, index, s)
                                    synonymWayMap[s] = oneWaySynonym
                                    if (words != null) {
                                        synonymMap[term] = words
                                    }
                                    logger.trace("EXT-SYN [{}] {} / {} / {} / {} / {}", setName, term, s, oneWaySynonym, syns, wordList)
                                    setAnalyzedResult(result, s, ANALYZE_SET_SYNONYM)
                                    val synWordList = result[ANALYZE_SET_SYNONYM]
                                    val list = if (synWordList != null && synWordList.isNotEmpty()) synWordList[synWordList.size - 1] else null
                                    for (synonym in syns) {
                                        val ss = synonym.toString()
                                        list?.add(ss)
                                        setAnalyzedResult(result, ss, ANALYZE_SET_FINAL)
                                    }
                                }
                            }
                        }
                    }
                    if (TokenTypes.FULL_STRING != type) {
                        tempTermList.add(term)
                    }
                }

                if (tempTermList.size > 1 && synonymDict != null) {
                    for (tempterm in tempTermList) {
                        // Current word
                        setAnalyzeSynonym(synonymDict, tempterm, client, index, result, synonymWayMap, synonymMap, setName, useForQuery)

                        // Previous term processing
                        if (prevTerm != null) {
                            val combineTermTwo = prevTerm + tempterm
                            setAnalyzeSynonym(synonymDict, combineTermTwo, client, index, result, synonymWayMap, synonymMap, setName, useForQuery)

                            // Previous + previous term processing
                            if (prePrevTerm != null) {
                                val combineTermThree = prePrevTerm + combineTermTwo
                                setAnalyzeSynonym(synonymDict, combineTermThree, client, index, result, synonymWayMap, synonymMap, setName, useForQuery)
                            }
                        }
                        prePrevTerm = prevTerm
                        prevTerm = tempterm
                    }
                }
                logger.trace("SYNONYM-WAY : {}", synonymWayMap)
            } catch (e: Exception) {
                logger.error("", e)
            }
        }

        // Synonym expansion method used in ranking viewer and management tool
        private fun setAnalyzeSynonym(
            dictionary: SynonymDictionary,
            combineTerm: String,
            client: NodeClient?,
            index: String?,
            result: MutableMap<String, MutableList<MutableList<String>>>,
            synonymWayMap: MutableMap<String, Boolean>,
            synonymMap: MutableMap<String, MutableList<String>>,
            setName: String?,
            useForQuery: Boolean
        ) {
            val dictData = dictionary.get(CharVector(combineTerm))
            if (dictData != null) {
                val syns = getAnalyzeSynonym(combineTerm, useForQuery)

                if (syns.isNotEmpty()) {
                    var wordList = result[ANALYZE_SET_SYNONYM]
                    val words = mutableListOf<String>()
                    wordList?.add(words)
                    words.add(combineTerm)
                    wordList = result[setName]
                    val words2 = if (wordList != null && wordList.isNotEmpty()) wordList[wordList.size - 1] else null

                    val oneWaySynonym = isOneWaySynonym(client, index, combineTerm)
                    synonymWayMap[combineTerm] = oneWaySynonym
                    synonymMap[combineTerm] = words
                    for (synonym in syns) {
                        val s = synonym.toString()
                        words.add(s)
                        if (ANALYZE_SET_NORMAL != setName && ANALYZE_SET_MODEL_NAME != setName && ANALYZE_SET_UNIT != setName) {
                            words2?.add(s)
                        }
                        if (useForQuery) {
                            setAnalyzedResult(result, s, ANALYZE_SET_FINAL)
                        }
                    }
                }
            }
        }

        // Synonym expansion method used in ranking viewer and management tool
        private fun getAnalyzeSynonym(combineTerm: String, useForQuery: Boolean): List<CharSequence> {
            val resultList = mutableListOf<CharSequence>()

            // Synonym expansion
            try {
                val analyzerStream = ProductNameAnalyzerProvider.getAnalyzer(combineTerm, true, true, true, true, false)
                val synAtr = analyzerStream.addAttribute(SynonymAttribute::class.java)
                val typeAttr = analyzerStream.addAttribute(TypeAttribute::class.java)

                analyzerStream.reset()
                while (analyzerStream.incrementToken()) {
                    val syns = synAtr.getSynonyms()
                    if (syns != null && syns.isNotEmpty()) {
                        for (synonym in syns) {
                            val type = typeAttr.type()
                            if (type == TokenTypes.FULL_STRING && useForQuery) {
                                resultList.add(synonym)
                            } else if (!useForQuery) {
                                resultList.add(synonym)
                            }
                        }
                    }
                }
            } catch (e: Exception) {
                logger.error("", e)
            }

            return resultList
        }

        @JvmStatic
        fun analyzeTextDetailWriteJSON(
            client: NodeClient?,
            text: String,
            stream: TokenStream,
            index: String?,
            detail: Boolean,
            writer: JSONWriter,
            useForQuery: Boolean
        ) {
            val result = mutableMapOf<String, MutableList<MutableList<String>>>()
            val synonymWayMap = mutableMapOf<String, Boolean>()
            val synonymMap = mutableMapOf<String, MutableList<String>>()
            var wordList: MutableList<MutableList<String>>?
            var words: MutableList<String>?
            analyzeTextDetail(client, text, stream, index, result, synonymWayMap, synonymMap, useForQuery)

            try {
                writer.`object`()
                    .key("query").value(text)
                    .key("result").array()
                if (detail) {
                    for (key in TreeSet(result.keys)) {
                        val label = ANALYSIS_RESULT_LABELS[key]
                        wordList = result[key]
                        logger.trace("TYPE:{} / {}", label, wordList)
                        val analyzed = StringBuilder()

                        when (key) {
                            ANALYZE_SET_FULL_STRING -> {
                                if (wordList != null && wordList.isNotEmpty()) {
                                    words = wordList[0]
                                    if (words.isNotEmpty()) {
                                        analyzed.append(words[0])
                                    }
                                }
                            }
                            ANALYZE_SET_STOPWORD -> {
                                if (wordList != null) {
                                    for (item in wordList) {
                                        if (analyzed.isNotEmpty()) {
                                            analyzed.append(COMMA).append(" ")
                                        }
                                        if (item.isNotEmpty()) {
                                            analyzed.append(item[0])
                                        }
                                    }
                                }
                            }
                            ANALYZE_SET_MODEL_NAME -> {
                                if (wordList != null) {
                                    for (item in wordList) {
                                        if (analyzed.isNotEmpty()) {
                                            analyzed.append(TAG_BR)
                                        }

                                        // Move full term keyword to the end of model name rule
                                        // 2021-03-17 Sun Jiho
                                        val fullTermKeyword = item[0]
                                        item.removeAt(0)
                                        item.add(fullTermKeyword)

                                        for (inx in item.indices) {
                                            val w = item[inx]
                                            if (inx == 0) {
                                                analyzed.append(TAG_STRONG.replace(REGEX_TAG_TEXT.toRegex(), Matcher.quoteReplacement(fullTermKeyword)))
                                                    .append(" ( ")
                                                analyzed.append(w)
                                            } else {
                                                if (inx > 0) {
                                                    analyzed.append(", ")
                                                }
                                                analyzed.append(w)
                                            }
                                        }
                                        analyzed.append(" ) ")
                                    }
                                }
                            }
                            ANALYZE_SET_UNIT -> {
                                if (wordList != null) {
                                    for (item in wordList) {
                                        if (analyzed.isNotEmpty()) {
                                            analyzed.append(TAG_BR)
                                        }
                                        var word: String? = null
                                        var data = StringBuilder()
                                        for (inx in item.indices) {
                                            val w = item[inx]
                                            if (inx == 0) {
                                                word = w
                                                analyzed.append(TAG_STRONG.replace(REGEX_TAG_TEXT.toRegex(), Matcher.quoteReplacement(w))).append(" : ")
                                            } else {
                                                if (inx > 1) {
                                                    data.append(", ")
                                                }
                                                data.append(w)
                                            }
                                        }
                                        if (word != null && synonymWayMap.containsKey(word)) {
                                            analyzed.append(data).append(TAG_BR).append(" >>> 동의어 : ")
                                            data = StringBuilder()
                                            words = synonymMap[word]
                                            if (words != null) {
                                                for (inx in 1 until words.size) {
                                                    val w = words[inx]
                                                    if (inx > 1) {
                                                        data.append(", ")
                                                    }
                                                    data.append(w)
                                                }
                                            }
                                            analyzed.append(data)
                                        } else {
                                            analyzed.append(data)
                                        }
                                    }
                                }
                            }
                            ANALYZE_SET_NORMAL -> {
                                if (wordList != null) {
                                    for (item in wordList) {
                                        if (analyzed.isNotEmpty()) {
                                            analyzed.append(COMMA).append(" ")
                                        }
                                        if (item.isNotEmpty()) {
                                            analyzed.append(item[0])
                                        }
                                    }
                                }
                            }
                            ANALYZE_SET_SYNONYM -> {
                                if (wordList != null) {
                                    for (item in wordList) {
                                        if (analyzed.isNotEmpty()) {
                                            analyzed.append(TAG_BR)
                                        }
                                        var word: String? = null
                                        val data = StringBuilder()
                                        for (inx in item.indices) {
                                            val w = item[inx]
                                            if (inx == 0) {
                                                word = w
                                                analyzed.append(TAG_STRONG.replace(REGEX_TAG_TEXT.toRegex(), Matcher.quoteReplacement(w))).append(" : ")
                                            } else {
                                                if (inx > 1) {
                                                    data.append(", ")
                                                }
                                                data.append(w)
                                            }
                                        }
                                        if (word != null && synonymWayMap.containsKey(word) && synonymWayMap[word] == true) {
                                            analyzed.append(data).append(TAG_BR).append(" >>> 단방향 : ").append(data)
                                        } else {
                                            analyzed.append(data)
                                        }
                                    }
                                }
                            }
                            ANALYZE_SET_COMPOUND -> {
                                if (wordList != null) {
                                    for (item in wordList) {
                                        if (analyzed.isNotEmpty()) {
                                            analyzed.append(TAG_BR)
                                        }
                                        for (inx in item.indices) {
                                            val w = item[inx]
                                            if (inx == 0) {
                                                analyzed.append(TAG_STRONG.replace(REGEX_TAG_TEXT.toRegex(), Matcher.quoteReplacement(w))).append(" : ")
                                            } else {
                                                if (inx > 1) {
                                                    analyzed.append(", ")
                                                }
                                                analyzed.append(w)
                                            }
                                        }
                                    }
                                }
                            }
                            ANALYZE_SET_FINAL -> {
                                if (wordList != null) {
                                    for (item in wordList) {
                                        if (analyzed.isNotEmpty()) {
                                            analyzed.append(COMMA).append(" ")
                                        }
                                        if (item.isNotEmpty()) {
                                            analyzed.append(item[0])
                                        }
                                    }
                                }
                            }
                        }
                        writer.`object`()
                            .key("key").value(label)
                            .key("value").value(analyzed)
                        writer.endObject()
                    }
                } else {
                    wordList = result[ANALYZE_SET_FINAL]
                    logger.trace("RESULT:{}", wordList)
                    if (wordList != null) {
                        for (item in wordList) {
                            if (item.isNotEmpty()) {
                                writer.value(item[0])
                            }
                        }
                    }
                }
                writer
                    .endArray()
                    .key("success").value(true)
                    .endObject()
            } catch (e: Exception) {
                logger.error("", e)
            }
        }

        /**
         * Create expanded search keywords for each term
         */
        @JvmStatic
        fun expansionKeyword(text: String, stream: TokenStream, writer: JSONWriter) {
            val termAttr = stream.addAttribute(CharTermAttribute::class.java)
            val typeAttr = stream.addAttribute(TypeAttribute::class.java)
            val extAttr = stream.addAttribute(ExtraTermAttribute::class.java)
            val synAttr = stream.addAttribute(SynonymAttribute::class.java)
            val offAttr = stream.addAttribute(OffsetAttribute::class.java)

            var termWords: MutableList<Any>
            var extraTermWords: MutableList<Any>
            val dictionary = getDictionary()
            val synonymDict = dictionary?.getDictionary(ProductNameDictionary.DICT_SYNONYM, SynonymDictionary::class.java)

            var syns: List<CharSequence>?

            val tempTermList = mutableListOf<String>()
            val hash = linkedMapOf<String, Any>()
            val combineTermSynonym = mutableMapOf<String, Any>()
            var extensionSynonym: MutableMap<String, Any>?

            var offset = intArrayOf(0, 0)
            var offsetPrev: IntArray

            try {
                stream.reset()
                while (stream.incrementToken()) {
                    offsetPrev = intArrayOf(offset[0], offset[1])
                    val term = termAttr.toString()
                    termWords = mutableListOf()
                    extraTermWords = mutableListOf()
                    val type = typeAttr.type()
                    offset = intArrayOf(offAttr.startOffset(), offAttr.endOffset())
                    logger.trace("TERM:{} / {}", term, type)

                    // Handle full term separately
                    if (type == TokenTypes.FULL_STRING) {
                        syns = synAttr.getSynonyms()
                        if (syns != null && syns.isNotEmpty()) {
                            termWords = mutableListOf()
                            val termList = divideTerm(text)
                            termWords.add(termList)

                            logger.trace("FULLTERM SYNONYM {} / {} ", term, syns)

                            for (synonym in syns) {
                                val s = synonym.toString()
                                val synonymList = s.split(" ")
                                if (synonymList.size > 1) {
                                    termWords.add(synonymList.toTypedArray())
                                } else {
                                    termWords.add(s)
                                }
                            }
                            combineTermSynonym[term] = termWords
                        }
                    } else {
                        // Store term for synonym expansion
                        tempTermList.add(term)
                        if (offset[0] < offsetPrev[1]) {
                            termWords.add(term)
                            offset = intArrayOf(offsetPrev[0], offsetPrev[1])
                        } else {
                            termWords.add(term)
                        }

                        syns = synAttr.getSynonyms()
                        if (syns != null && syns.isNotEmpty()) {
                            logger.trace("SYNONYM {} / {} ", term, syns)
                            for (synonym in syns) {
                                val s = synonym.toString()
                                val synonymList = s.split(" ")
                                if (synonymList.size > 1) {
                                    termWords.add(synonymList.toTypedArray())
                                } else {
                                    termWords.add(s)
                                }
                            }
                        }

                        val iter = extAttr.iterator()
                        if (iter != null && iter.hasNext()) {
                            while (iter.hasNext()) {
                                val s = iter.next()
                                logger.trace("EXT {} / {} / {}", term, s, termWords)
                                extraTermWords.add(s)
                                syns = synAttr.getSynonyms()
                                if (syns != null && syns.isNotEmpty()) {
                                    extensionSynonym = mutableMapOf()
                                    val extSynonymList = mutableListOf<String>()
                                    // Remove original extension from list when extension has synonyms
                                    extraTermWords.remove(s)

                                    logger.trace("EXT-SYN {} / {} / {}", term, s, syns)

                                    for (synonym in syns) {
                                        logger.trace("synonym : {}", synonym)
                                        extSynonymList.add(synonym.toString())
                                    }
                                    logger.trace("synonymList : {} - {}", s, extSynonymList)
                                    extensionSynonym[s] = extSynonymList
                                    if (extensionSynonym.isNotEmpty()) {
                                        extraTermWords.add(extensionSynonym)
                                    }
                                }
                            }
                        }
                        if (extraTermWords.isNotEmpty()) {
                            termWords.add(extraTermWords)
                        }
                    }
                    logger.trace("term : {} - {}", term, termWords)

                    // Only for non-full terms. Full terms (with synonyms) are already stored in fullTermHash
                    if (termWords.isEmpty()) {
                        combineTermSynonym[term] = arrayOf<Any>(term)
                    } else {
                        if (type != TokenTypes.FULL_STRING) {
                            hash[term] = termWords.toTypedArray()
                        }
                    }
                }

                // Expand synonyms for 2 or more space-separated terms
                if (tempTermList.size > 1 && synonymDict != null) {
                    var prevTerm: String? = null
                    var prePrevTerm: String? = null

                    for (term in tempTermList) {
                        if (prevTerm != null) {
                            val combineTermTwo = prevTerm + term
                            putSynonymData(combineTermSynonym, synonymDict, combineTermTwo)

                            if (prePrevTerm != null) {
                                val combineTermThree = prePrevTerm + combineTermTwo
                                putSynonymData(combineTermSynonym, synonymDict, combineTermThree)
                            }
                        }
                        prePrevTerm = prevTerm
                        prevTerm = term
                    }
                }

                writer.`object`()
                    .key("query").value(text)
                    .key("result").value(hash)
                    .key("synonym").value(combineTermSynonym)
                    .endObject()
            } catch (e: Exception) {
                logger.error("", e)
            }
        }

        // combineTermSynonym: final synonym map to return, synonymDict: synonym dictionary, combineTerm: word to find
        private fun putSynonymData(
            combineTermSynonym: MutableMap<String, Any>,
            synonymDict: SynonymDictionary,
            combineTerm: String
        ) {
            val dictData = synonymDict.get(CharVector(combineTerm))

            // If synonyms exist
            if (dictData != null) {
                combineTermSynonym[combineTerm] = removeDuplicates(findSynonymTerm(combineTerm, dictData))
            }
        }

        private fun findSynonymTerm(combineTerm: String, dictData: Array<CharSequence>): ArrayList<Any> {
            val result = ArrayList<Any>()

            result.add(divideTerm(combineTerm))
            for (v in dictData) {
                val value = v.toString()

                // Synonym expansion
                try {
                    val analyzerStream = ProductNameAnalyzerProvider.getAnalyzer(value, true, false, false, false, false)
                    val termAtr = analyzerStream.addAttribute(CharTermAttribute::class.java)
                    analyzerStream.reset()
                    val subResult = ArrayList<Any>()
                    while (analyzerStream.incrementToken()) {
                        val temp = termAtr.toString()
                        subResult.add(temp)
                    }
                    result.add(subResult)
                } catch (e: Exception) {
                    logger.error("", e)
                }
            }

            return result
        }

        // Method to separate keyword into morpheme units
        private fun divideTerm(keyword: String): ArrayList<Any> {
            val result = ArrayList<Any>()

            // Synonym expansion
            try {
                val analyzerStream = ProductNameAnalyzerProvider.getAnalyzer(keyword, true, false, false, false, false)
                val termAtr = analyzerStream.addAttribute(CharTermAttribute::class.java)
                analyzerStream.reset()
                while (analyzerStream.incrementToken()) {
                    val temp = termAtr.toString()
                    result.add(temp)
                }
            } catch (e: Exception) {
                logger.error("", e)
            }

            return result
        }

        // ArrayList deduplication
        private fun <T> removeDuplicates(list: ArrayList<T>): ArrayList<T> {
            val newList = ArrayList<T>()

            for (element in list) {
                if (!newList.contains(element)) {
                    newList.add(element)
                }
            }

            return newList
        }

