    /**
     * Distribute signal to each node
     */
    private fun distribute(client: NodeClient, action: String, body: JSONObject, selfDist: Boolean) {
        val localNodeId = client.localNodeId
        val infoRequest = NodesInfoRequest()
        infoRequest.clear()
            .addMetrics(NodesInfoMetrics.Metric.JVM.metricName())
            .addMetrics(NodesInfoMetrics.Metric.OS.metricName())
            .addMetrics(NodesInfoMetrics.Metric.PROCESS.metricName())
            .addMetrics(NodesInfoMetrics.Metric.HTTP.metricName())
            .addMetrics(NodesInfoMetrics.Metric.PLUGINS.metricName())
            .addMetrics(NodesInfoMetrics.Metric.INDICES.metricName())

        try {
            val response: NodesInfoResponse = client.admin().cluster().nodesInfo(infoRequest).get()
            val nodes: List<NodeInfo> = response.nodes
            for (node in nodes) {
                // Distribute only to nodes other than self
                if (!selfDist && localNodeId == node.node.id) {
                    continue
                }
                var hasPlugin = false
                val address: TransportAddress = node.getInfo(HttpInfo::class.java).address().publishAddress()
                // Distribute only to nodes with product name analyzer plugin
                val plugins: List<PluginRuntimeInfo> = node.getInfo(PluginsAndModules::class.java).pluginInfos
                for (info in plugins) {
                    if (info.descriptor().classname == AnalysisProductNamePlugin::class.java.name) {
                        hasPlugin = true
                        break
                    }
                }
                if (hasPlugin) {
                    logger.debug("NODE: {}:{}", address.address, address.port)
                    doRestRequest(address.address, address.port, action, body)
                }
            }
        } catch (e: Exception) {
            logger.error("", e)
        }
    }

    /**
     * Send REST signal to a specific node
     */
    private fun doRestRequest(address: String, port: Int, action: String, body: JSONObject): String {
        val sb = StringBuilder()
        var con: HttpURLConnection? = null
        var ostream: OutputStream? = null
        var reader: BufferedReader? = null
        try {
            val url = "http://$address:$port$BASE_URI/$action"
            logger.debug("SEND REQUEST {}", url)
            con = URL(url).openConnection() as HttpURLConnection
            con.requestMethod = "POST"
            con.setRequestProperty("Content-Type", "application/json")
            con.doOutput = true
            ostream = con.outputStream
            ostream.write(body.toString().toByteArray())
            ostream.flush()
            val responseCode = con.responseCode
            if (responseCode == HttpURLConnection.HTTP_CREATED) {
                logger.trace("RESPONSE:{}", responseCode)
                reader = BufferedReader(InputStreamReader(con.inputStream))
                var rl: String?
                while (reader.readLine().also { rl = it } != null) {
                    sb.append(rl).append("\r\n")
                }
                logger.trace("RESPONSE:{}", sb)
            }
        } catch (e: Exception) {
            logger.error("", e)
        } finally {
            try { ostream?.close() } catch (ignore: Exception) { }
            try { reader?.close() } catch (ignore: Exception) { }
        }
        return sb.toString()
    }

    /**
     * Text product name detailed analysis
     */
    private fun analyzeTextAction(request: RestRequest, client: NodeClient, writer: JSONWriter) {
        var jparam = JSONObject()
        var index = request.param("index", ES_DICTIONARY_INDEX)
        var text = request.param("text", "")
        var detail = request.paramAsBoolean("detail", true)
        var useForQuery = request.paramAsBoolean("useForQuery", true)
        var useSynonym = request.paramAsBoolean("useSynonym", true)
        var useStopword = request.paramAsBoolean("useStopword", false)
        var useFullString = request.paramAsBoolean("useFullString", true)
        var test = false
        if (GET != request.method()) {
            jparam = parseRequestBody(request)
            index = jparam.optString("index", ES_DICTIONARY_INDEX)
            text = jparam.optString("text", "")
            detail = jparam.optBoolean("detail", true)
            useForQuery = jparam.optBoolean("useForQuery", true)
            useSynonym = jparam.optBoolean("useSynonym", true)
            useStopword = jparam.optBoolean("useStopword", false)
            useFullString = jparam.optBoolean("useFullString", true)
            test = jparam.optBoolean("test", false)
        }

        var stream: TokenStream? = null
        try {
            stream = ProductNameAnalyzerProvider.getAnalyzer(text, useForQuery, useSynonym, useStopword, useFullString, false)
            analyzeTextDetailWriteJSON(client, text, stream, index, detail, writer, useForQuery)
        } finally {
            try { stream?.close() } catch (ignore: Exception) { }
        }

        if (test) {
            distribute(client, ACTION_TEST, jparam, true)
        }
    }

    /**
     * Text product name analysis
     * Multi-parameter processing
     */
    private fun analyzeMultiParamsAction(request: RestRequest, client: NodeClient, writer: JSONWriter) {
        var jparam = JSONObject()

        logger.debug("multi-params Action")
        // Index is fixed
        val index = ES_DICTIONARY_INDEX

        // Query expansion
        val useForQuery = false
        val useSynonym = true
        val useStopword = false
        val useFullString = true

        val analyzeMap = mutableMapOf<String, String>()
        if (GET != request.method()) {
            // POST processing
            jparam = parseRequestBody(request)
            for (key in jparam.keySet()) {
                analyzeMap[key] = jparam.optString(key, "")
            }
        } else {
            // GET processing
            try {
                for (key in request.params().keys) {
                    if (key == "action" || key == "pretty") continue
                    analyzeMap[key] = URLDecoder.decode(request.param(key, ""), "UTF-8")
                }
            } catch (e: Exception) {
                logger.error("UnsupportedEncodingException Catched !!! >>>> \n" + e.message)
                writer.key("success").value(false)
                logger.debug("error >>> {}", e)
            }
        }

        var stream: TokenStream? = null
        writer.key("result").`object`()
        try {
            for (key in analyzeMap.keys) {
                val value = analyzeMap[key] ?: ""
                logger.debug("key : {} :::::: value : {}", key, value)
                stream = ProductNameAnalyzerProvider.getAnalyzer(value, useForQuery, useSynonym, useStopword, useFullString, false)
                val list = analyzeMultiParamsText(client, value, stream, index, useForQuery)
                if (list.isNotEmpty()) {
                    writer.key(key).array()
                    for (item in list) {
                        writer.value(item)
                    }
                    writer.endArray()
                }
                stream.close()
            }
        } catch (ignore: Exception) {
            writer.endObject()
            writer.key("success").value(false)
            logger.debug("exception >>> {}", ignore)
            logger.error("Exception Catched !!! >>>> \n" + ignore.message)
        } finally {
            writer.endObject()
            writer.key("success").value(true)
        }
    }

