    private fun getSynonymListAction(request: RestRequest, client: NodeClient, writer: JSONWriter) {
        var jparam = JSONObject()
        var keyword = ""
        val useForQuery = true
        val useSynonym = true
        val useStopword = false
        val useFullString = true

        logger.debug("get-synonym-list start")
        if (GET != request.method()) {
            jparam = parseRequestBody(request)
            keyword = jparam.optString("keyword", "")
        } else {
            try {
                keyword = URLDecoder.decode(request.param("keyword", ""), "UTF-8")
            } catch (e: Exception) {
                logger.error("UnsupportedEncodingException Catched !!! >>>> \n" + e.message)
