import org.gradle.api.tasks.testing.logging.TestLogEvent

buildscript {
    dependencies {
        classpath(fileTree(mapOf("dir" to "lib", "include" to listOf("*.jar"))))
    }
}

plugins {
    id("java-library")
    id("maven-publish")
    kotlin("jvm") version "2.1.0"
}

group = "com.danawa.search"
version = "1.0.0"

java {
    toolchain {
        languageVersion.set(JavaLanguageVersion.of(21))
    }
}

kotlin {
    jvmToolchain(21)
}

tasks.compileJava {
    options.encoding = "UTF-8"
    options.isIncremental = true
    options.isFork = true
    options.isFailOnError = false
}

tasks.compileTestJava {
    options.encoding = "UTF-8"
}

tasks.compileKotlin {
    compilerOptions {
        freeCompilerArgs.add("-Xjsr305=strict")
    }
}

repositories {
    mavenCentral()
    mavenLocal()
}

sourceSets {
    main {
        java {
            setSrcDirs(listOf("src/main/java"))
            exclude("Tester.java")
        }
        kotlin {
            setSrcDirs(listOf("src/main/kotlin"))
        }
        resources {
            setSrcDirs(listOf("src/main/resources"))
            exclude("**/**")
        }
    }
    test {
        java {
            setSrcDirs(listOf("src/test/java"))
        }
        kotlin {
            setSrcDirs(listOf("src/test/kotlin"))
        }
    }
}

// ES 9.x Entitlement 정책 파일을 JAR에 포함
tasks.jar {
    from("src/main/plugin-metadata") {
        into("plugin-metadata")
    }
}

dependencies {
    // Kotlin
    implementation(kotlin("stdlib"))

    // Existing dependencies
    implementation("commons-io:commons-io:1.3.2")
    implementation("org.elasticsearch:elasticsearch:9.1.2")
    implementation("org.apache.logging.log4j:log4j-core:2.11.1")
    implementation("org.json:json:2019+")
    implementation("org.yaml:snakeyaml:2.2")

    // JUnit 5 (replacing JUnit 4)
    testImplementation(platform("org.junit:junit-bom:5.10.2"))
    testImplementation("org.junit.jupiter:junit-jupiter")
    testRuntimeOnly("org.junit.platform:junit-platform-launcher")

    // JUnit 4 backward compatibility (for incremental migration)
    testImplementation("junit:junit:4.13.2")
    testRuntimeOnly("org.junit.vintage:junit-vintage-engine")
}

val copyToDependencies by tasks.registering(Copy::class) {
    from(configurations.runtimeClasspath) {
        include("json-*", "slf4j-api*", "snakeyaml-*", "commons-io-*")
    }
    from("src/main/resources") {
        include("*.properties")
        include("*.policy")
        include("*.yml")
    }
    // ES 9.x Entitlement 정책 파일 - 플러그인 루트에 직접 배치 (plugin-metadata/ 하위가 아님!)
    from("src/main/plugin-metadata") {
        include("entitlement-policy.yaml")
    }
    into(layout.buildDirectory.dir("libs"))
}

val copyJars by tasks.registering(Copy::class) {
    dependsOn(tasks.jar)
    dependsOn(copyToDependencies)
    from(configurations.runtimeClasspath) {
        include("*.jar")
    }
    from(tasks.jar.flatMap { it.archiveFile }) {
        include("*.jar")
    }
    duplicatesStrategy = DuplicatesStrategy.EXCLUDE
    into(layout.buildDirectory.dir("jars"))
}

tasks.build {
    println("BUILDING..")
}

/**
 * gradle 커맨드에서 다음과 같이 테스트 실행 가능
 * ./gradlew --no-daemon test --tests -DLOG_LEVEL=TRACE -DSYSPROP_LAUNCH_FOR_BUILD=false ProductNameAnalysisFilterTest.testFilter
 */
tasks.test {
    useJUnitPlatform()  // Enable JUnit 5

    val launchForBuild = System.getProperty("SYSPROP_LAUNCH_FOR_BUILD")
    val dictSetting = System.getProperty("SYSPROP_TEST_DICTIONARY_SETTING")
    val logLevel = System.getProperty("LOG_LEVEL")

    if (launchForBuild == "false") {
        systemProperty("SYSPROP_LAUNCH_FOR_BUILD", "false")
        testLogging {
            showStandardStreams = true
            events(TestLogEvent.PASSED, TestLogEvent.SKIPPED, TestLogEvent.FAILED)
        }
    } else {
        systemProperty("SYSPROP_LAUNCH_FOR_BUILD", "true")
    }

    if (dictSetting.isNullOrEmpty()) {
        systemProperty("SYSPROP_TEST_DICTIONARY_SETTING", "INTERNAL")
    } else {
        systemProperty("SYSPROP_TEST_DICTIONARY_SETTING", dictSetting)
    }

    if (logLevel.isNullOrEmpty()) {
        System.getProperty("DEBUG")?.let { systemProperty("LOG_LEVEL", it) }
    } else {
        systemProperty("LOG_LEVEL", logLevel)
    }

    System.getProperty("SYSPROP_TEST_DICTIONARY_LOAD_EXTRA")?.let {
        systemProperty("SYSPROP_TEST_DICTIONARY_LOAD_EXTRA", it)
    }
    System.getProperty("SYSPROP_SAMPLE_TEXT_PATH")?.let {
        systemProperty("SYSPROP_SAMPLE_TEXT_PATH", it)
    }
    System.getProperty("log4j.configurationFile")?.let {
        systemProperty("log4j.configurationFile", it)
    }
    systemProperty("file.encoding", "UTF-8")

    dependsOn("cleanTest")
}

// ES 플러그인 배포용 ZIP 파일 생성
val pluginZip by tasks.registering(Zip::class) {
    dependsOn(copyToDependencies, copyJars)

    archiveBaseName.set("analysis-product2")
    archiveVersion.set(version.toString())
    destinationDirectory.set(layout.buildDirectory.dir("distributions"))

    from(layout.buildDirectory.dir("libs")) {
        include("**/*")
    }
}

tasks.build {
    dependsOn(copyToDependencies, copyJars, pluginZip)
}

